/**
 * Pull every non-primary node's own local disaster-recovery backups (written
 * by scripts/backup-vms.sh + backup-pve-config.sh, running locally on each
 * node — see onboard-node.sh's "local backups" step) onto the primary via the
 * node-agent, into a per-node tree that scripts/backup-offsite.sh then
 * replicates to Dropbox alongside the primary's own backups.
 *
 * WHY THIS EXISTS: before this, node-2 and node-3 had zero backup coverage
 * anywhere off their own single chassis — their local vzdump archives never
 * left the box they were made on, so losing either node lost every VM on it
 * with no recovery path. This is the primary-side half of closing that gap;
 * see docs/DOCUMENTATION.md's "Multi-node synergy" section for the full
 * design (the node-agent is the ONLY sanctioned channel for a host-level
 * operation on a non-primary node — no SSH, ever, matches every other
 * cross-node operation in this codebase).
 *
 * Destination layout: /tank/backup/nodes/<node-name>/<platform|status>/...
 * — mirrors each node's manifest exactly (files no longer listed are deleted
 * locally too), so this directory's size tracks each node's own KEEP_LAST
 * retention rather than growing forever.
 *
 * Runs as the first step of scripts/backup-offsite.sh, before the Dropbox
 * sync, so a fresh node backup actually makes it off-site the same night it
 * was made. A single unreachable node does not fail the whole run — its
 * failure is recorded in the status file (the same "honesty banner" pattern
 * lib/monitoring.ts's nodeStorageUsage() already uses per-node) and the
 * PRIMARY's own db/host-config/vms sync still proceeds.
 *
 * Exit code: non-zero only if EVERY non-primary node failed, or if there
 * are no non-primary nodes to report at all is NOT an error (a single-node
 * deployment has nothing to collect). backup-offsite.sh treats this script's
 * exit code as informational, not fatal — node connectivity problems are
 * surfaced via /admin/backups' per-node status, not by red-lighting the
 * primary's own off-site sync.
 */
import { readdir, stat, mkdir, rm } from "node:fs/promises";
import path from "node:path";
import { db } from "../lib/db";
import { agentBackupManifest, agentDownloadBackupFile, type AgentNode } from "../lib/node-agent";

const DEST_ROOT = process.env.NXEON_NODE_BACKUP_DIR || "/tank/backup/nodes";
const STATUS_DIR = process.env.NXEON_BACKUP_STATUS_DIR || "/tank/backup/status";
const STATUS_FILE = path.join(STATUS_DIR, "node-collect.json");

function log(msg: string) {
  console.log(`[${new Date().toISOString()}] ${msg}`);
}

type NodeResult = {
  node: string;
  ok: boolean;
  filesTotal: number;
  filesCopied: number;
  filesPruned: number;
  bytesCopied: number;
  error: string | null;
  at: string;
};

/** Every local file under destDir/{platform,status} not named in `keep` is
 *  removed — mirrors the node's own retention (backup-vms.sh's KEEP_LAST)
 *  onto this collected copy so it never grows past what the source node
 *  itself still holds. */
async function pruneStale(destDir: string, keep: Set<string>): Promise<number> {
  let pruned = 0;
  for (const sub of ["platform", "status"]) {
    const dir = path.join(destDir, sub);
    let names: string[];
    try {
      names = await readdir(dir);
    } catch {
      continue;
    }
    for (const name of names) {
      const rel = `${sub}/${name}`;
      if (keep.has(rel)) continue;
      await rm(path.join(dir, name), { force: true });
      pruned++;
    }
  }
  return pruned;
}

async function collectOne(node: AgentNode): Promise<NodeResult> {
  const at = new Date().toISOString();
  const destDir = path.join(DEST_ROOT, node.name);
  try {
    const entries = await agentBackupManifest(node);
    let copied = 0;
    let bytes = 0;
    for (const entry of entries) {
      // entry.path is already validated server-side against the agent's own
      // BACKUP_REL_RE allowlist — it can only ever be "platform/..." or
      // "status/...". path.join with no ".." possible from that shape.
      const dest = path.join(destDir, entry.path);
      let needsCopy = true;
      try {
        const st = await stat(dest);
        needsCopy = st.size !== entry.size;
      } catch {
        needsCopy = true; // doesn't exist locally yet
      }
      if (!needsCopy) continue;
      await agentDownloadBackupFile(node, entry.path, dest);
      copied++;
      bytes += entry.size;
    }
    const pruned = await pruneStale(destDir, new Set(entries.map((e) => e.path)));
    log(`${node.name}: ${entries.length} file(s) on the node, ${copied} copied, ${pruned} pruned locally`);
    return { node: node.name, ok: true, filesTotal: entries.length, filesCopied: copied, filesPruned: pruned, bytesCopied: bytes, error: null, at };
  } catch (e: any) {
    const msg = String(e?.message ?? e).slice(0, 500);
    log(`${node.name}: FAILED — ${msg}`);
    return { node: node.name, ok: false, filesTotal: 0, filesCopied: 0, filesPruned: 0, bytesCopied: 0, error: msg, at };
  }
}

async function main() {
  const nodes = await db.node.findMany({
    where: { isPrimary: false, enabled: true },
    select: { id: true, name: true, publicIp: true, agentPort: true, agentTokenEnc: true },
  });

  await mkdir(STATUS_DIR, { recursive: true }).catch(() => {});

  const { writeFile } = await import("node:fs/promises");

  if (nodes.length === 0) {
    log("no non-primary nodes to collect from — single-chassis deployment, nothing to do");
    await writeFile(STATUS_FILE, JSON.stringify({ at: new Date().toISOString(), nodes: [] }, null, 2), { mode: 0o644 });
    process.exit(0);
  }

  const results: NodeResult[] = [];
  for (const node of nodes) {
    results.push(await collectOne(node));
  }

  await writeFile(STATUS_FILE, JSON.stringify({ at: new Date().toISOString(), nodes: results }, null, 2), { mode: 0o644 });

  const anyOk = results.some((r) => r.ok);
  const allFailed = results.length > 0 && !anyOk;
  if (allFailed) {
    log("every non-primary node failed to collect — see errors above");
    process.exit(1);
  }
  process.exit(0);
}

main().catch((e) => {
  console.error("[collect-node-backups] fatal:", e);
  process.exit(1);
});

}

