const IPV4_RE = /^(?:(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)\.){3}(?:25[0-5]|2[0-4]\d|1\d\d|[1-9]?\d)$/;
const CHAIN_RE = /^[A-Z0-9_]{1,40}$/;
const STORAGE_RE = /^[a-zA-Z0-9_-]{1,60}$/;
// Matches exactly the filenames worker/index.ts's provision() ever asks for:
// nxeon-<vmid>.yaml. Nothing else is ever written or deleted by this agent.
const FILENAME_RE = /^nxeon-\d+\.yaml$/;
// Root of this node's own local disaster-recovery backups (see
// scripts/backup-vms.sh / backup-pve-config.sh, which write here directly —
// this agent never writes into it, only reads). Matches those scripts'
// own NXEON_PLATFORM_BACKUP_DIR/NXEON_BACKUP_STATUS_DIR defaults
// (/tank/backup/platform, /tank/backup/status), one level up.
const BACKUP_ROOT = process.env.NXEON_AGENT_BACKUP_ROOT || "/tank/backup";
// Allowlist of relative paths this agent will ever list or stream — exactly
// the filenames backup-pve-config.sh / backup-vms.sh produce. Read-only:
// there is no write/delete counterpart, unlike the snippet endpoints above —
// the primary only ever pulls from here, never pushes.
const BACKUP_REL_RE =
  /^(platform\/(host-config-\d{8}-\d{6}\.tar\.gz|vzdump-qemu-\d+-\d{4}_\d{2}_\d{2}-\d{2}_\d{2}_\d{2}\.(vma\.zst|log)|vm-names\.txt)|status\/(host-config|vm-backup)\.json)$/;

