/**
 * Mod auto-update policy: who gets updated, when. Pure (the clock is passed in).
 *
 *  effectiveMode — server default + per-mod override + the clientRequired gate.
 *  inWindow      — off-peak window in the server's local time.
 *  runGate       — window + "nobody online" + per-node/global caps + back-off,
 *                  each failure with the plain reason the run was deferred.
 */
import type { Mode } from "./types";

export type ModePolicyInput = {
  serverMode: Mode;
  modOverride: Mode | null | undefined;
  pinned: boolean;
  clientRequired: boolean | null | undefined;
  /** Owner explicitly allowed AUTO for client-required mods (with the warning shown). */
  clientModsAuto: boolean;
};

export function effectiveMode(p: ModePolicyInput): { mode: Mode; reason: string } {
  if (p.pinned) return { mode: "OFF", reason: "Pinned — never updated automatically." };
  const want: Mode = p.modOverride ?? p.serverMode;
  if (want === "AUTO" && p.clientRequired === true && !p.clientModsAuto) {
    return {
      mode: "NOTIFY",
      reason: "Players need this mod too, so it isn't updated automatically (they'd be locked out until they update). Turn on \"also auto-update mods players need\" to change that.
    };
  }
  if (want === "AUTO" && p.clientRequired == null && !p.clientModsAuto) {
    return { mode: "NOTIFY", reason: "We can't tell whether players need this mod, so we only notify. Turn on \"also auto-update mods players need\" to auto-update it anyway." };
  }
  const src = p.modOverride ? "set for this mod" : "server default";
  return { mode: want, reason: want === "AUTO" ? `Auto-update (${src}).` : want === "NOTIFY" ? `Notify only (${src}).` : `Off (${src}).` };
}

/** Region code → IANA timezone, for the default off-peak window. */
export const REGION_TZ: Record<string, string> = {
  sgp1: "Asia/Singapore",
  bhs1: "America/Toronto",
  gra1: "Europe/Paris",
  rbx1: "Europe/Paris",
  waw1: "Europe/Warsaw",
  fsn1: "Europe/Berlin",
  nbg1: "Europe/Berlin",
  hel1: "Europe/Helsinki",
  ash1: "America/New_York",
  hil1: "America/Los_Angeles",
};

export function regionTimezone(region: string | null | undefined): string {
  return (region && REGION_TZ[region]) || "UTC";
}

export function isValidTimezone(tz: string): boolean {
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: tz });
    return true;
  } catch {
    return false;
  }
}

/** Local hour (0..23) at `now` in `tz`. */
export function localHour(now: Date, tz: string): number {
  const h = new Intl.DateTimeFormat("en-US", { timeZone: isValidTimezone(tz) ? tz : "UTC", hour: "numeric", hourCycle: "h23" }).format(now);
  return Number(h) % 24;
}

/** [start, end) in local hours; start === end means "any time"; wraps midnight (22 → 4). */
export function inWindow(now: Date, tz: string, start: number, end: number): boolean {
  if (start === end) return true;
  const h = localHour(now, tz);
  return start < end ? h >= start && h < end : h >= start || h < end;
}

