export const OFFSITE_ROOT_DEFAULT = "nxeon-backups";
export const MANIFEST_SCHEMA = "nxeon-backup-manifest/1";

export type BackupCategory = "hypervisor" | "vm" | "database" | "platform";
export const BACKUP_CATEGORIES: readonly BackupCategory[] = ["hypervisor", "vm", "database", "platform"];

/** Directory name used under a run folder for each category. */
export const CATEGORY_DIR: Record<BackupCategory, string> = {
  hypervisor: "hypervisor",
  vm: "vms",
  database: "databases",
  platform: "platform",
};

/** Lower-case a-z0-9- only, max 40 chars; never empty. Names come from customers (hostnames). */
export function slug(name: string | null | undefined): string {
  const s = String(name ?? "")
    .toLowerCase()
    .replace(/[^a-z0-9-]+/g, "-")
    .replace(/-+/g, "-")
    .replace(/^-|-$/g, "")
    .slice(0, 40)
    .replace(/-$/, "");
  return s || "unnamed";
}

/** Node names are operator-chosen ("node-2", "primary"); keep them path-safe. */
export function nodeSlug(node: string): string {
  return slug(node);
}

const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

export function runDir(date: string, node: string): string {
  if (!DATE_RE.test(date)) throw new Error(`bad run date ${date}`);
  return `${date.slice(0, 4)}/${date}/${nodeSlug(node)}`;
}

export type RemoteRef = { category: BackupCategory; date: string; node: string; vmid?: number; vmName?: string; plainName: string };

/** Path (relative to the off-site root) of one encrypted artifact. */
export function remotePath(ref: RemoteRef): string {
  const dir = runDir(ref.date, ref.node);
  if (!/^[A-Za-z0-9._-]+$/.test(ref.plainName)) throw new Error(`unsafe file name ${ref.plainName}`);
  switch (ref.category) {
    case "vm": {
      if (!Number.isInteger(ref.vmid) || (ref.vmid as number) < 1) throw new Error("vm artifact needs a vmid");
      return `${dir}/vms/${ref.vmid}-${slug(ref.vmName)}/${ref.plainName}.age`;
    }
    default:
      return `${dir}/${CATEGORY_DIR[ref.category]}/${ref.plainName}.age`;
  }
}

export type ParsedRemote = { date: string; node: string; category: BackupCategory; vmid?: number; vmSlug?: string; plainName: string; path: string };

/** Inverse of remotePath(); null for anything that is not a backup artifact (manifest.json, README, junk). */
export function parseRemotePath(path: string): ParsedRemote | null {
  const m = /^(\d{4})\/(\d{4}-\d{2}-\d{2})\/([a-z0-9-]+)\/(hypervisor|vms|databases|platform)\/(?:(\d+)-([a-z0-9-]+)\/)?([A-Za-z0-9._-]+)\.age$/.exec(path);
  if (!m) return null;
  const [, year, date, node, dir, vmid, vmSlug, plainName] = m;
  if (date.slice(0, 4) !== year) return null;
  const category = (Object.keys(CATEGORY_DIR) as BackupCategory[]).find((c) => CATEGORY_DIR[c] === dir) as BackupCategory;
  if (category === "vm" ? !vmid : !!vmid) return null;
  return { date, node, category, plainName, path, ...(vmid ? { vmid: Number(vmid), vmSlug } : {}) };
}

/** Timestamp (UTC ms) embedded in an artifact's plain name, or null. Formats produced by our scripts + vzdump + pg dumps. */
export function timestampFromName(plainName: string): number | null {
  let m = /(\d{4})_(\d{2})_(\d{2})-(\d{2})_(\d{2})_(\d{2})/.exec(plainName); // vzdump 2026_10_02-04_37_55
  if (!m) m = /(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})(\d{2})/.exec(plainName); // host/db/platform 20261002-043742
  if (!m) return null;
  const t = Date.UTC(+m[1], +m[2] - 1, +m[3], +m[4], +m[5], +m[6]);
  return Number.isFinite(t) ? t : null;
}

export type ManifestItem = {
  category: BackupCategory;
  /** Path relative to the run folder (<YYYY>/<date>/<node>/), e.g. "vms/105-studionexis-soul/vzdump-....vma.zst.age". */
  path: string;
  plainName: string;
  vmid?: number;
  vmName?: string;
  /** infra | customer-vps | game | template (from the node's planner) */
  class?: string;
  /** Bytes / sha256 of the ENCRYPTED object as stored. */
  bytes: number;
  sha256: string;
  /** Bytes / sha256 of the plaintext the archive decrypts to - verify after restore. */
  plainBytes: number;
  plainSha256: string;
  /** mtime of the source archive (ISO). */
  sourceAt: string;
  restore: string;
};

export type Manifest = {
  schema: typeof MANIFEST_SCHEMA;
  run: {
    date: string;
    node: string;
    startedAt: string;
    finishedAt: string;
    host?: { hostname?: string; pveVersion?: string; kernel?: string };
    /** nxeon repo commit of the code that made this run. */
    nxeonCommit?: string;
  };
  encryption: { scheme: "age"; recipients: string[]; note: string };
  items: ManifestItem[];
  totals: { items: number; bytes: number; plainBytes: number };
};

/** One-line, copy-pasteable restore hint per category (full runbook: docs/DISASTER-RECOVERY.md). */
export function restoreHint(item: Pick<ManifestItem, "category" | "plainName" | "vmid">): string {
  const dec = `age -d -i <identity> <file>.age`;
  switch (item.category) {
    case "vm":
      return `${dec} > ${item.plainName}; qmrestore ${item.plainName} <NEW-never-used-vmid> --storage vmdata   (vzdump archive, zstd)`;
    case "database":
