    totals: { items: items.length, bytes: items.reduce((s, i) => s + i.bytes, 0), plainBytes: items.reduce((s, i) => s + i.plainBytes, 0) },
  };
}

const SHA_RE = /^[0-9a-f]{64}$/;

/** Returns a list of problems; empty = valid. Used by the uploader before it writes a manifest and by the restore test. */
export function validateManifest(x: unknown): string[] {
  const p: string[] = [];
  const m = x as Manifest;
  if (!m || typeof m !== "object") return ["manifest is not an object"];
  if (m.schema !== MANIFEST_SCHEMA) p.push(`schema must be ${MANIFEST_SCHEMA}`);
  if (!m.run || !DATE_RE.test(m.run.date ?? "")) p.push("run.date missing or malformed");
  if (!m.run?.node) p.push("run.node missing");
  if (!m.encryption || m.encryption.scheme !== "age" || !Array.isArray(m.encryption.recipients) || m.encryption.recipients.length < 1) p.push("encryption.recipients missing");
  else if (m.encryption.recipients.some((r) => !/^age1[a-z0-9]+$/.test(r))) p.push("encryption.recipients must be age1... PUBLIC keys only");
  if (!Array.isArray(m.items)) return [...p, "items missing"];
  const seen = new Set<string>();
  for (const [i, it] of m.items.entries()) {
    const at = `items[${i}]`;
    if (!BACKUP_CATEGORIES.includes(it.category)) p.push(`${at}.category invalid`);
    if (typeof it.path !== "string" || it.path.startsWith("/") || it.path.includes("..")) p.push(`${at}.path unsafe`);
    if (seen.has(it.path)) p.push(`${at}.path duplicated`);
    seen.add(it.path);
    if (!SHA_RE.test(it.sha256 ?? "")) p.push(`${at}.sha256 invalid`);
    if (!SHA_RE.test(it.plainSha256 ?? "")) p.push(`${at}.plainSha256 invalid`);
    if (!(it.bytes > 0)) p.push(`${at}.bytes must be > 0`);
    if (!(it.plainBytes > 0)) p.push(`${at}.plainBytes must be > 0`);
    if (it.category === "vm" && !Number.isInteger(it.vmid)) p.push(`${at}.vmid required for a vm item`);
  }
  if (m.totals && m.totals.items !== m.items.length) p.push("totals.items does not match items.length");
  return p;
}

const human = (n: number) => (n >= 2 ** 30 ? `${(n / 2 ** 30).toFixed(1)} GiB` : n >= 2 ** 20 ? `${(n / 2 ** 20).toFixed(1)} MiB` : `${(n / 1024).toFixed(1)} KiB`);

/** Human README placed next to manifest.json. */
export function renderRunReadme(m: Manifest): string {
  const lines: string[] = [];
  lines.push(`Nxeon off-site backup - ${m.run.date} - node ${m.run.node}`);
  lines.push("=".repeat(60));
  lines.push(`Run: ${m.run.startedAt} -> ${m.run.finishedAt}`);
  if (m.run.host?.hostname) lines.push(`Host: ${m.run.host.hostname}${m.run.host.pveVersion ? ` (${m.run.host.pveVersion})` : ""}${m.run.host.kernel ? `, kernel ${m.run.host.kernel}` : ""}`);
  if (m.run.nxeonCommit) lines.push(`Platform commit: ${m.run.nxeonCommit}`);
  lines.push("");
  lines.push("Every file ending in .age is encrypted with age to these PUBLIC keys:");
  for (const r of m.encryption.recipients) lines.push(`  ${r}`);
  lines.push("Decrypt with the matching PRIVATE identity file kept off the servers by the owner:");
  lines.push("  age -d -i identity.txt <file>.age > <file>");
  lines.push("");
  lines.push(`${m.totals.items} item(s), ${human(m.totals.bytes)} stored.`);
  lines.push("");
  for (const cat of BACKUP_CATEGORIES) {
    const its = m.items.filter((i) => i.category === cat);
    if (!its.length) continue;
    lines.push(`[${CATEGORY_DIR[cat]}]`);
    for (const i of its) {
      lines.push(`  ${i.path}`);
      lines.push(`      ${human(i.bytes)} stored / ${human(i.plainBytes)} plain   sha256(stored)=${i.sha256}`);
      lines.push(`      restore: ${i.restore}`);
    }
    lines.push("");
  }
  lines.push("Full rebuild-from-nothing runbook: docs/DISASTER-RECOVERY.md in the nxeon repository");
  lines.push("(a copy is also inside the platform/ archive as the git bundle).");
  return lines.join("\n") + "\n";
}

export const ROOT_README = `Nxeon platform backups
======================
Layout:  <YYYY>/<YYYY-MM-DD>/<node>/{hypervisor,vms/<vmid>-<name>,databases,platform}/
Each run folder holds manifest.json (sizes, sha256, versions, restore hint per file) and README.txt.
Contents are encrypted with age; the private key is held off the servers by the owner.
To restore: see docs/DISASTER-RECOVERY.md (rebuild from nothing), or the restore hint in the manifest.
Do not delete, rename or edit files in here by hand: the platform's retention job owns this tree.
`;
