  if (/^platform-\d{8}-\d{6}\.tar\.gz$/.test(n)) return { category: "platform" };
  return null;
}

/** Index of what is already off-site: node -> category -> (vmid|0) -> sorted artifact timestamps + names. */
export function indexRemote(files: readonly RemoteFile[]) {
  const names = new Set<string>(); // `${node}/${plainName}`
  const newest = new Map<string, number>(); // `${node}|${category}|${vmid}` -> newest source timestamp (ms)
  for (const f of files) {
    const p = parseRemotePath(f.path);
    if (!p) continue;
    names.add(`${p.node}/${p.plainName}`);
    const ts = timestampFromName(p.plainName) ?? f.mtimeMs;
    const k = `${p.node}|${p.category}|${p.vmid ?? 0}`;
    if (!newest.has(k) || ts > (newest.get(k) as number)) newest.set(k, ts);
  }
  return { names, newest };
}

const CLASS_RANK: Record<string, number> = { infra: 0, "customer-vps": 1, game: 2, template: 9 };

export function planUploads(inv: readonly NodeInventory[], remote: readonly RemoteFile[], now: number, cfg: PlanConfig): Plan {
  const idx = indexRemote(remote);
  const skipped: Skipped[] = [];
  const cands: UploadTask[] = [];

  for (const n of inv) {
    if (!n.ok) {
      skipped.push({ node: n.node, rel: "*", why: "inventory could not be read this run - nothing planned for this node (absence of evidence is not evidence)" });
      continue;
    }
    const vmById = new Map(n.vms.map((v) => [v.vmid, v]));
    const byKey = new Map<string, InvFile>(); // newest source file per (category, vmid)
    for (const f of n.files) {
      const c = categoryOfSource(f.rel);
      if (!c) continue; // logs, status, vm-names: not backup artifacts
      if (now - f.mtimeMs < cfg.minAgeMs) {
        skipped.push({ node: n.node, rel: f.rel, why: "still being written (younger than minAge)" });
        continue;
      }
      const k = `${c.category}|${c.vmid ?? 0}`;
      const cur = byKey.get(k);
      if (!cur || f.mtimeMs > cur.mtimeMs) byKey.set(k, f);
    }

    for (const [k, f] of byKey) {
      const [catS, vmidS] = k.split("|");
      const category = catS as BackupCategory;
      const vmid = Number(vmidS) || undefined;
      const plainName = base(f.rel);
      const onRemote = idx.names.has(`${n.node}/${plainName}`);
      const date = cfg.runDate;
      let reason = "";
      let vm: InvVm | undefined;

      if (category === "vm") {
        vm = vmById.get(vmid as number);
        if (!vm) { skipped.push({ node: n.node, rel: f.rel, why: "orphan archive: the VM no longer exists on this node (kept locally; not uploaded)" }); continue; }
        if (vm.template && n.node !== cfg.templateNode) { skipped.push({ node: n.node, rel: f.rel, why: `template: uploaded from ${cfg.templateNode} only (reproducible via scripts/build-templates.sh)` }); continue; }
        if (onRemote) { skipped.push({ node: n.node, rel: f.rel, why: "this exact archive is already off-site" }); continue; }
        const last = idx.newest.get(`${n.node}|vm|${vmid}`);
        const cadenceMs = Math.max(0.5, vm.offsiteCadenceDays - cfg.cadenceSlackDays) * DAY;
        if (last !== undefined && now - last < cadenceMs) {
          skipped.push({ node: n.node, rel: f.rel, why: `newest off-site copy is ${((now - last) / DAY).toFixed(1)} d old; cadence ${vm.offsiteCadenceDays} d` });
          continue;
        }
        reason = last === undefined ? "no off-site copy exists yet" : `off-site copy is ${((now - last) / DAY).toFixed(1)} d old (cadence ${vm.offsiteCadenceDays} d)`;
      } else {
        if (onRemote) { skipped.push({ node: n.node, rel: f.rel, why: "already off-site" }); continue; }
        reason = "newest archive not yet off-site";
      }
      cands.push({
        category, node: n.node, via: n.via, rel: f.rel, plainName, size: f.size, mtimeMs: f.mtimeMs, reason,
        ...(vm ? { vmid: vm.vmid, vmName: vm.name, vmClass: vm.class } : {}),
        remote: remotePath({ category, date, node: n.node, vmid, vmName: vm?.name, plainName }),
      });
    }
  }

  // Small + critical first: databases, platform, hypervisor, then VMs by class (infra first),
  // never-uploaded before refresh, then oldest first. The byte budget then cuts off the BIG tail.
  const catRank: Record<BackupCategory, number> = { database: 0, platform: 1, hypervisor: 2, vm: 3 };
  cands.sort((a, b) =>
    catRank[a.category] - catRank[b.category] ||
    (CLASS_RANK[a.vmClass ?? ""] ?? 5) - (CLASS_RANK[b.vmClass ?? ""] ?? 5) ||
    (a.reason.startsWith("no off-site") ? 0 : 1) - (b.reason.startsWith("no off-site") ? 0 : 1) ||
    a.mtimeMs - b.mtimeMs ||
    a.rel.localeCompare(b.rel));

  const tasks: UploadTask[] = [];
  const deferred: UploadTask[] = [];
  let bytes = 0;
  for (const t of cands) {
    // Always take the first VM even if it alone exceeds the budget (a 19 GB image must be able to go),
    // but never take a non-VM item out of budget order: they are tiny and always fit.
    const fits = bytes + t.size <= cfg.byteBudget || tasks.length === 0 || t.category !== "vm";
    if (tasks.length < cfg.maxFiles && fits) { tasks.push(t); bytes += t.size; } else deferred.push(t);
  }
  return { tasks, skipped, deferred, bytes };
}

// ---------------------------------------------------------------------------------------------
// Retention
// ---------------------------------------------------------------------------------------------

export type Keep = { daily: number; weekly: number; monthly: number };
export type RetentionPolicy = {
  database: Keep;
  hypervisor: Keep;
  platform: Keep;
  vm: Record<string, Keep> & { default: Keep };
  /** A deleted VM's backups are purged this many days after its newest copy (customer data must not live forever). */
  orphanDays: number;
  /** Safety cap: never plan more deletions than this in one run. */
  maxDeletes: number;
};

export const DEFAULT_RETENTION: RetentionPolicy = {
  database: { daily: 7, weekly: 4, monthly: 6 },
  hypervisor: { daily: 7, weekly: 4, monthly: 6 },
  platform: { daily: 7, weekly: 4, monthly: 6 },
  vm: {
    infra: { daily: 3, weekly: 2, monthly: 1 },
    "customer-vps": { daily: 0, weekly: 2, monthly: 1 },
    game: { daily: 0, weekly: 1, monthly: 1 },
    template: { daily: 0, weekly: 0, monthly: 2 },
    default: { daily: 0, weekly: 2, monthly: 1 },
  },
  orphanDays: 30,
  maxDeletes: 400,
};

function isoWeekKey(ms: number): string {
  const d = new Date(ms);
  const t = new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
  const day = t.getUTCDay() || 7;
  t.setUTCDate(t.getUTCDate() + 4 - day);
  const y = t.getUTCFullYear();
  const w = Math.ceil(((t.getTime() - Date.UTC(y, 0, 1)) / DAY + 1) / 7);
  return `${y}-W${w}`;
}

/** Which timestamps (newest first, one backup each) survive a daily/weekly/monthly policy. Newest is ALWAYS kept. */
export function keepSet(tsList: readonly number[], k: Keep): Set<number> {
  const sorted = [...tsList].sort((a, b) => b - a);
  const keep = new Set<number>();
  if (sorted.length) keep.add(sorted[0]);
  const take = (key: (ms: number) => string, n: number) => {
    const seen = new Set<string>();
    for (const ts of sorted) {
      const g = key(ts);
      if (seen.has(g)) continue;
      if (seen.size >= n) break;
      seen.add(g);
      keep.add(ts);
    }
  };
  take((ms) => new Date(ms).toISOString().slice(0, 10), k.daily);
  take(isoWeekKey, k.weekly);
  take((ms) => new Date(ms).toISOString().slice(0, 7), k.monthly);
  return keep;
}

export type RetentionPlan = { delete: { path: string; why: string }[]; keep: number; capped: boolean };

/**
 * `readOk`: nodes whose inventory was read this run - deletions for a node whose state we could not read are
 * never planned (a VM that merely looks absent because the agent was down must not lose its backups).
 */
export function planRetention(
  remote: readonly RemoteFile[],
  vmsByNode: ReadonlyMap<string, ReadonlyMap<number, InvVm>>,
  readOk: ReadonlySet<string>,
  now: number,
  policy: RetentionPolicy = DEFAULT_RETENTION,
): RetentionPlan {
  const groups = new Map<string, { path: string; ts: number }[]>();
  const meta = new Map<string, { node: string; category: BackupCategory; vmid?: number }>();
  for (const f of remote) {
    const p = parseRemotePath(f.path);
    if (!p) continue;
    const gk = `${p.node}|${p.category}|${p.vmid ?? 0}`;
    (groups.get(gk) ?? groups.set(gk, []).get(gk)!).push({ path: f.path, ts: timestampFromName(p.plainName) ?? f.mtimeMs });
    meta.set(gk, { node: p.node, category: p.category, vmid: p.vmid });
  }
  const del: { path: string; why: string }[] = [];
  let keepCount = 0;
  for (const [gk, items] of groups) {
    const m = meta.get(gk)!;
    if (!readOk.has(m.node)) { keepCount += items.length; continue; }
    let k: Keep;
    if (m.category === "vm") {
      const vm = vmsByNode.get(m.node)?.get(m.vmid as number);
      if (!vm) {
        // VM is gone from a node we read successfully: purge after orphanDays since its newest copy.
        const newest = Math.max(...items.map((i) => i.ts));
        if (now - newest > policy.orphanDays * DAY) { for (const i of items) del.push({ path: i.path, why: `orphan VM ${m.vmid}: newest copy older than ${policy.orphanDays} d` }); }
        else keepCount += items.length;
        continue;
      }
      k = policy.vm[vm.class] ?? policy.vm.default;
    } else k = policy[m.category];
    const ks = keepSet(items.map((i) => i.ts), k);
    for (const i of items) {
      if (ks.has(i.ts)) keepCount++;
      else del.push({ path: i.path, why: `outside daily ${k.daily} / weekly ${k.weekly} / monthly ${k.monthly}` });
    }
  }
  del.sort((a, b) => a.path.localeCompare(b.path));
  const capped = del.length > policy.maxDeletes;
  return { delete: capped ? del.slice(0, policy.maxDeletes) : del, keep: keepCount, capped };
}

/** Projected steady-state off-site size (bytes) for a set of newest-archive sizes under a retention policy. Used by the design doc + the admin page. */
export function projectSteadyState(
  items: readonly { category: BackupCategory; class?: string; bytes: number; cadenceDays: number }[],
  policy: RetentionPolicy = DEFAULT_RETENTION,
): { total: number; byCategory: Record<BackupCategory, number> } {
  const byCategory: Record<BackupCategory, number> = { hypervisor: 0, vm: 0, database: 0, platform: 0 };
  for (const it of items) {
    const k = it.category === "vm" ? policy.vm[it.class ?? "default"] ?? policy.vm.default : policy[it.category];
    // copies kept = distinct daily/weekly/monthly restore points, capped by how often a new one is made
    const perWeek = Math.max(1, 7 / Math.max(1, it.cadenceDays));
    const daily = Math.min(k.daily, Math.ceil(perWeek * 1));
    const copies = daily + Math.min(k.weekly, 4) + Math.min(k.monthly, 6);
    byCategory[it.category] += it.bytes * Math.max(1, copies);
  }
  return { total: BACKUP_CATEGORIES.reduce((s, c) => s + byCategory[c], 0), byCategory };
}
