    counts[new Date(t).getUTCHours()]++;
    n++;
  }
  return { visitAvg: counts.map((c) => c / Math.max(1, days)), visits: n };
}

/** Region code -> IANA timezone (kept in step with lib/mod-autoupdate/policy.ts REGION_TZ; duplicated to stay dependency-free). */
export const REGION_TZ: Record<string, string> = {
  sgp1: "Asia/Singapore", sgp2: "Asia/Singapore", bhs1: "America/Toronto", gra1: "Europe/Paris", rbx1: "Europe/Paris",
  waw1: "Europe/Warsaw", fsn1: "Europe/Berlin", nbg1: "Europe/Berlin", hel1: "Europe/Helsinki", ash1: "America/New_York", hil1: "America/Los_Angeles",
};

/** UTC offset in hours (may be fractional) of `tz` at instant `at`. */
export function tzOffsetHours(tz: string, at: number): number {
  try {
    const parts = new Intl.DateTimeFormat("en-US", { timeZone: tz, hourCycle: "h23", year: "numeric", month: "2-digit", day: "2-digit", hour: "2-digit", minute: "2-digit", second: "2-digit" }).formatToParts(new Date(at));
    const g = (t: string) => Number(parts.find((p) => p.type === t)?.value);
    const asUtc = Date.UTC(g("year"), g("month") - 1, g("day"), g("hour"), g("minute"), g("second"));
    return (asUtc - Math.floor(at / 1000) * 1000) / 3_600_000;
  } catch {
    return 0;
  }
}

export type WindowChoice = {
  startUtcHour: number; // 0..23
  hours: number;
  /** HH:MM UTC, the format /etc/nxeon/backup-window.json and the runner expect. */
  startUtc: string;
  basis: "telemetry" | "region-default" | "no-region-fallback";
  /** Mean weighted activity inside the chosen window and over the whole day (so the benefit is visible). */
  windowMean: number;
  dayMean: number;
  peakHourUtc: number;
  explanation: string;
};

export type SelectArgs = {
  playerAvg?: number[];
  visitAvg?: number[];
  playerHours?: number;
  visits?: number;
  /** Observed days; fewer than minDays falls back to the region default. */
  days: number;
  region?: string | null;
  durationHours: number;
  now: number;
  /** Visits are a fleet-wide proxy; weight them far below real concurrent players. */
  visitWeight?: number;
  minDays?: number;
  /** Need at least this many player-hours to trust the player signal. */
  minPlayerHours?: number;
  /** Local hour the window should START at when the data cannot decide (and as a tie-break). */
  preferredLocalStart?: number;
};

const pad = (n: number) => String(n).padStart(2, "0");
const mod = (n: number, m: number) => ((n % m) + m) % m;

/** Pick the least-active contiguous window. Circular over the day (a window may cross 00:00 UTC). */
export function selectBackupWindow(a: SelectArgs): WindowChoice {
  const dur = Math.max(1, Math.min(12, Math.round(a.durationHours)));
  const tz = a.region ? REGION_TZ[a.region] : undefined;
  const prefLocal = a.preferredLocalStart ?? 2; // local 02:00-06:00 by default
  const fallback = (basis: WindowChoice["basis"], why: string): WindowChoice => {
    const off = tz ? tzOffsetHours(tz, a.now) : 0;
    const startUtcHour = mod(Math.round(prefLocal - off), 24);
    return { startUtcHour, hours: dur, startUtc: `${pad(startUtcHour)}:00`, basis, windowMean: 0, dayMean: 0, peakHourUtc: -1, explanation: why };
  };

  const minDays = a.minDays ?? 7;
  const players = a.playerAvg && a.playerAvg.length === HOURS ? a.playerAvg : null;
  const enoughPlayers = !!players && (a.playerHours ?? 0) >= (a.minPlayerHours ?? 20);
  const visits = a.visitAvg && a.visitAvg.length === HOURS ? a.visitAvg : null;
  const enoughVisits = !!visits && (a.visits ?? 0) >= 200;

  if (a.days < minDays || (!enoughPlayers && !enoughVisits)) {
    return fallback(
      tz ? "region-default" : "no-region-fallback",
      `Only ${a.days} day(s) / ${Math.round(a.playerHours ?? 0)} player-hours of data - not enough to measure. ` +
        (tz ? `Using ${tz} local ${pad(prefLocal)}:00-${pad(mod(prefLocal + dur, 24))}:00.` : "No region known; using UTC clock hours."),
    );
  }

  // Weighted per-hour load. Players are normalised so one busy node's absolute scale does not matter.
  const pMax = enoughPlayers ? Math.max(...(players as number[]), 1e-9) : 1;
  const vMax = enoughVisits ? Math.max(...(visits as number[]), 1e-9) : 1;
  const vw = a.visitWeight ?? 0.25;
  const load = new Array<number>(HOURS).fill(0);
  for (let h = 0; h < HOURS; h++) {
    load[h] = (enoughPlayers ? (players as number[])[h] / pMax : 0) + (enoughVisits ? vw * ((visits as number[])[h] / vMax) : 0);
  }
  // Smooth by +/-1 hour so one noisy hour does not decide the window, then slide a window over the circle.
  const smooth = load.map((_, h) => (load[mod(h - 1, 24)] + 2 * load[h] + load[mod(h + 1, 24)]) / 4);
  const off = tz ? tzOffsetHours(tz, a.now) : 0;
  const prefStartUtc = mod(Math.round(prefLocal - off), 24);

  let best = { start: 0, sum: Infinity, dist: Infinity };
  for (let s = 0; s < HOURS; s++) {
    let sum = 0;
    for (let i = 0; i < dur; i++) sum += smooth[mod(s + i, 24)];
    const dist = Math.min(mod(s - prefStartUtc, 24), mod(prefStartUtc - s, 24));
    // Strictly lower load wins; near-ties (within 2%) go to the window closest to the local small hours.
    if (sum < best.sum * 0.98 || (sum <= best.sum * 1.02 && dist < best.dist)) best = { start: s, sum: Math.min(sum, best.sum), dist };
  }
  const windowMean = best.sum / dur;
  const dayMean = smooth.reduce((x, y) => x + y, 0) / HOURS;
  const peak = smooth.indexOf(Math.max(...smooth));
  return {
    startUtcHour: best.start,
    hours: dur,
    startUtc: `${pad(best.start)}:00`,
    basis: "telemetry",
    windowMean,
    dayMean,
    peakHourUtc: peak,
    explanation:
      `Measured over ${a.days} d (${Math.round(a.playerHours ?? 0)} player-hours, ${a.visits ?? 0} visits): quietest ${dur} h start at ${pad(best.start)}:00 UTC ` +
      `(mean load ${(windowMean / Math.max(dayMean, 1e-9) * 100).toFixed(0)}% of the daily average; busiest hour ${pad(peak)}:00 UTC).`,
  };
}

/** Does a UTC instant fall inside a chosen window? (used by tests and by the admin page to show "inside/outside now") */
export function inWindowUtc(now: number, w: Pick<WindowChoice, "startUtcHour" | "hours">): boolean {
  const h = new Date(now).getUTCHours();
  return mod(h - w.startUtcHour, 24) < w.hours;
}
