 * lib/fleet-alert-plan.ts (prefix "OFFSITE-BACKUP:").
 */

export const OFFSITE_ALERT_PREFIX = "OFFSITE-BACKUP:";
const H = 3_600_000;
const D = 24 * H;

export type VmInfo = {
  vmid: number;
  name: string;
  class: string; // infra | customer-vps | game | template
  template: boolean;
  offsiteCadenceDays: number;
  localCadenceDays: number;
  /** newest local vzdump archive (epoch ms) or null */
  localNewestMs: number | null;
};

export type TimerState = { name: string; enabled: boolean; active: boolean; lastTriggerMs: number | null };

export type NodeHealth = {
  node: string;
  nodeId: string;
  reachable: boolean;
  error?: string;
  /** The node's backup timers (legacy nxeon-backup-vms.timer and/or nxeon-backup-run.timer). */
  timers: TimerState[];
  vms: VmInfo[];
  hypervisorNewestMs: number | null;
  backupFs: { freeBytes: number; totalBytes: number } | null;
  /** Largest local archive on the node, to check a new one would fit. */
  largestArchiveBytes: number | null;
};

export type OffsiteState = {
  read: boolean;
  error?: string;
  /** `${node}|${category}|${vmid or 0}` -> newest source timestamp (ms) on the remote. */
  newest: Record<string, number>;
  usedBytes: number | null;
  totalBytes: number | null;
  timerEnabled: boolean | null;
  timerActive: boolean | null;
  /** age of last successful upload run, from offsite.json */
  lastUploadOkMs: number | null;
  encrypted: boolean | null;
};

export type FreshnessInput = {
  now: number;
  primaryNode: string;
  nodes: NodeHealth[];
  offsite: OffsiteState;
  restoreTest: { lastMs: number | null; lastOk: boolean | null } | null;
};

export type Thresholds = {
  dbWarnH: number; dbCritH: number;
  hypWarnH: number; hypCritH: number;
  platformWarnH: number; platformCritH: number;
  vmWarnExtraDays: number; vmCritExtraDays: number; // added to cadence (crit also doubles it)
  localWarnExtraDays: number; localCritExtraDays: number;
  diskWarnPct: number; diskCritPct: number; diskMinFreeBytes: number;
  quotaWarnPct: number; quotaCritPct: number;
  restoreWarnDays: number; restoreCritDays: number;
};

export const DEFAULT_THRESHOLDS: Thresholds = {
  dbWarnH: 36, dbCritH: 72,
  hypWarnH: 36, hypCritH: 72,
  platformWarnH: 48, platformCritH: 96,
  vmWarnExtraDays: 2, vmCritExtraDays: 4,
  localWarnExtraDays: 1.5, localCritExtraDays: 4,
  diskWarnPct: 15, diskCritPct: 8, diskMinFreeBytes: 25 * 2 ** 30,
  quotaWarnPct: 70, quotaCritPct: 85,
  restoreWarnDays: 10, restoreCritDays: 21,
};

export type Finding = {
  node: string;
  nodeId: string;
  code: string;
  severity: "WARN" | "CRITICAL";
  dimension: string;
  title: string;
  detail: string;
};

const ageH = (now: number, t: number | null | undefined) => (t == null ? Infinity : (now - t) / H);
const fmtAge = (h: number) => (h === Infinity ? "never" : h < 48 ? `${h.toFixed(0)} h` : `${(h / 24).toFixed(1)} d`);

export function evaluateFreshness(input: FreshnessInput, th: Thresholds = DEFAULT_THRESHOLDS): Finding[] {
  const out: Finding[] = [];
  const { now, offsite } = input;
  const primary = input.nodes.find((n) => n.node === input.primaryNode) ?? input.nodes[0];
  const fleet = { node: primary?.node ?? input.primaryNode, nodeId: primary?.nodeId ?? "primary" };
  const add = (f: Omit<Finding, "dimension"> & { scope: string }) => {
    const { scope, ...rest } = f;
    out.push({ ...rest, dimension: `${OFFSITE_ALERT_PREFIX}${scope}` });
  };

  // ---- off-site machinery (fleet level, attached to the primary) -----------------
  if (offsite.timerEnabled === false || offsite.timerActive === false) {
    add({
      ...fleet, code: "TIMER", scope: "TIMER", severity: "CRITICAL",
      title: "Off-site backup timer is NOT running",
      detail: `nxeon-backup-offsite.timer is ${offsite.timerEnabled === false ? "disabled" : "inactive"}, so nothing is being copied off this chassis. ` +
        `Enable with: systemctl enable --now nxeon-backup-offsite.timer (deploy/backup/nxeon-backup-offsite.timer).`,
    });
  }
  if (offsite.encrypted === false) {
    add({ ...fleet, code: "ENCRYPTION", scope: "ENCRYPTION", severity: "CRITICAL", title: "Off-site backups are being uploaded UNENCRYPTED", detail: "Archives contain customer data and secrets. The uploader reports encryption off or no recipients file. Fix /etc/nxeon/backup-recipients.txt (nxeon-backup-crypt.sh check)." });
  }
  if (!offsite.read) {
    add({ ...fleet, code: "REMOTE", scope: "REMOTE", severity: "CRITICAL", title: "Cannot read the off-site store", detail: `Listing the off-site remote failed${offsite.error ? `: ${offsite.error.slice(0, 200)}` : ""}. Until it can be read, off-site freshness is UNVERIFIED (not OK).` });
  } else {
    // quota
    if (offsite.usedBytes != null && offsite.totalBytes) {
      const pct = (offsite.usedBytes / offsite.totalBytes) * 100;
      if (pct >= th.quotaWarnPct) {
        add({ ...fleet, code: "QUOTA", scope: "QUOTA", severity: pct >= th.quotaCritPct ? "CRITICAL" : "WARN", title: `Off-site store ${pct.toFixed(0)}% full`, detail: `${(offsite.usedBytes / 2 ** 40).toFixed(2)} of ${(offsite.totalBytes / 2 ** 40).toFixed(2)} TiB used. Retention runs nightly; check the retention plan or add capacity.` });
      }
    }
    // database + platform (primary only)
    const dbAge = ageH(now, offsite.newest[`${input.primaryNode}|database|0`]);
    if (dbAge > th.dbWarnH) add({ ...fleet, code: "STALE-DB", scope: "STALE:db", severity: dbAge > th.dbCritH ? "CRITICAL" : "WARN", title: "Newest off-site database backup is stale", detail: `Newest off-site Postgres dump is ${fmtAge(dbAge)} old (warn ${th.dbWarnH} h / critical ${th.dbCritH} h).` });
    const plAge = ageH(now, offsite.newest[`${input.primaryNode}|platform|0`]);
    if (plAge > th.platformWarnH) add({ ...fleet, code: "STALE-PLATFORM", scope: "STALE:platform", severity: plAge > th.platformCritH ? "CRITICAL" : "WARN", title: "Newest off-site platform snapshot is stale", detail: `Secrets/.env/nginx/certs/git snapshot is ${fmtAge(plAge)} old off-site (warn ${th.platformWarnH} h / critical ${th.platformCritH} h).` });
  }

  // ---- per node ----------------------------------------------------------------------
  for (const n of input.nodes) {
    const id = { node: n.node, nodeId: n.nodeId };
    if (!n.reachable) {
      add({ ...id, code: "AGENT", scope: "AGENT", severity: "WARN", title: `Backup state of ${n.node} unreadable`, detail: `The node-agent on ${n.node} did not answer${n.error ? `: ${n.error.slice(0, 160)}` : ""}. Its backups are UNVERIFIED until it does.` });
      continue;
    }

    // the node's own timers
    const live = n.timers.filter((t) => t.enabled && t.active);
    if (live.length === 0) {
      add({ ...id, code: "LOCAL-TIMER", scope: "LOCAL-TIMER", severity: "CRITICAL", title: `No backup timer is running on ${n.node}`, detail: `${n.node} has no enabled+active backup timer (${n.timers.map((t) => `${t.name}: ${t.enabled ? "enabled" : "disabled"}/${t.active ? "active" : "inactive"}`).join(", ") || "none installed"}). New guests on it are not being backed up at all.` });
    }

    // local VM archives
    const none: string[] = [], stale: string[] = [];
    let worstLocal: "WARN" | "CRITICAL" = "WARN";
    for (const v of n.vms) {
      if (v.template) continue;
      const age = ageH(now, v.localNewestMs);
      if (v.localNewestMs == null) { none.push(`${v.vmid} ${v.name}`); continue; }
      const warn = (v.localCadenceDays + th.localWarnExtraDays) * 24;
      const crit = (v.localCadenceDays + th.localCritExtraDays) * 24;
      if (age > warn) { stale.push(`${v.vmid} ${v.name} (${fmtAge(age)})`); if (age > crit) worstLocal = "CRITICAL"; }
    }
    if (none.length) add({ ...id, code: "LOCAL-NONE", scope: "LOCAL-NONE", severity: "CRITICAL", title: `${none.length} VM(s) on ${n.node} have NO backup at all`, detail: `Never backed up locally: ${none.slice(0, 12).join(", ")}${none.length > 12 ? ` and ${none.length - 12} more` : ""}.` });
    if (stale.length) add({ ...id, code: "LOCAL-STALE", scope: "LOCAL-STALE", severity: worstLocal, title: `${stale.length} VM(s) on ${n.node} have a stale local backup`, detail: stale.slice(0, 12).join(", ") + (stale.length > 12 ? ` and ${stale.length - 12} more` : "") });

    // hypervisor config
    const hypAge = ageH(now, n.hypervisorNewestMs);
    if (n.hypervisorNewestMs != null && hypAge > th.hypWarnH && n.node !== undefined) {
      // local freshness only matters if off-site is read-able; off-site check below is the real gate
    }

    // disk
    if (n.backupFs && n.backupFs.totalBytes > 0) {
      const freePct = (n.backupFs.freeBytes / n.backupFs.totalBytes) * 100;
      const need = (n.largestArchiveBytes ?? 0) * 1.5;
      const tooSmall = n.backupFs.freeBytes < Math.max(th.diskMinFreeBytes, need);
      if (freePct < th.diskWarnPct || tooSmall) {
        add({ ...id, code: "DISK", scope: "DISK", severity: freePct < th.diskCritPct || tooSmall ? "CRITICAL" : "WARN", title: `Backup storage on ${n.node} is almost full`, detail: `${(n.backupFs.freeBytes / 2 ** 30).toFixed(1)} GiB free of ${(n.backupFs.totalBytes / 2 ** 30).toFixed(0)} GiB (${freePct.toFixed(0)}%). The next archive may not fit${n.backupFs.totalBytes < 100 * 2 ** 30 ? "; the backup directory is on a small filesystem - give it its own ZFS dataset" : ""}.` });
      }
    }

    // off-site freshness per category + VM
    if (offsite.read) {
      const hy = ageH(now, offsite.newest[`${n.node}|hypervisor|0`]);
      if (hy > th.hypWarnH) add({ ...id, code: "STALE-HYP", scope: "STALE:hypervisor", severity: hy > th.hypCritH ? "CRITICAL" : "WARN", title: `Off-site hypervisor config of ${n.node} is stale`, detail: `Newest off-site hypervisor snapshot for ${n.node} is ${fmtAge(hy)} old (warn ${th.hypWarnH} h / critical ${th.hypCritH} h).` });

      const miss: string[] = [];
      let worst: "WARN" | "CRITICAL" = "WARN";
      for (const v of n.vms) {
        if (v.template && n.node !== input.primaryNode) continue; // templates: one canonical copy
        const t = offsite.newest[`${n.node}|vm|${v.vmid}`];
        const age = ageH(now, t);
        const warn = (v.offsiteCadenceDays + th.vmWarnExtraDays) * 24;
        const crit = (v.offsiteCadenceDays * 2 + th.vmCritExtraDays) * 24;
        if (age > warn) {
          miss.push(`${v.vmid} ${v.name} [${v.class}] ${fmtAge(age)}`);
          if (age > crit && (v.class === "infra" || age !== Infinity)) worst = "CRITICAL";
          if (age === Infinity && v.class === "infra") worst = "CRITICAL";
        }
      }
      if (miss.length) add({ ...id, code: "STALE-VMS", scope: "STALE:vms", severity: worst, title: `${miss.length} VM(s) on ${n.node} have no recent off-site copy`, detail: miss.slice(0, 12).join("; ") + (miss.length > 12 ? `; and ${miss.length - 12} more` : "") });
    }
  }

  // ---- restore test ------------------------------------------------------------------
  const rt = input.restoreTest;
  if (rt) {
    if (rt.lastOk === false) add({ ...fleet, code: "RESTORE-TEST", scope: "RESTORE-TEST", severity: "CRITICAL", title: "The last restore test FAILED", detail: "A backup that cannot be restored is not a backup. See the restore-test log (scripts/backup/nxeon-restore-test.sh) before trusting any archive." });
    else {
      const d = rt.lastMs == null ? Infinity : (now - rt.lastMs) / D;
      if (d > th.restoreWarnDays) add({ ...fleet, code: "RESTORE-TEST", scope: "RESTORE-TEST", severity: d > th.restoreCritDays ? "CRITICAL" : "WARN", title: "No recent successful restore test", detail: `Last successful restore test: ${d === Infinity ? "never" : `${d.toFixed(0)} days ago`} (warn ${th.restoreWarnDays} d / critical ${th.restoreCritDays} d).` });
    }
  }
  return out;
}

/** The inventory the sweep stores for the admin page is itself evidence: if the checker stops, say so. */
export function inventoryStale(generatedAtMs: number | null, now: number, maxAgeH = 12): boolean {
  return generatedAtMs == null || now - generatedAtMs > maxAgeH * H;
}

/** One-line headline for the admin page (worst severity wins). */
export function headline(findings: readonly Finding[]): { level: "ok" | "warn" | "critical"; text: string } {
  const crit = findings.filter((f) => f.severity === "CRITICAL").length;
  const warn = findings.length - crit;
  if (crit) return { level: "critical", text: `${crit} critical, ${warn} warning${warn === 1 ? "" : "s"}` };
  if (warn) return { level: "warn", text: `${warn} warning${warn === 1 ? "" : "s"}` };
  return { level: "ok", text: "All backup checks pass" };
}
