/**
 * Streaming encrypt-and-upload (age -> rclone rcat) with hashing in the same pass.
 *
 * source stream -> sha256(plain) -> `age -R <recipients>` -> sha256(cipher) -> `rclone rcat <remote>`
 *
 * Nothing is staged on disk (a 19 GB archive needs no 19 GB scratch copy) and the
 * plaintext only ever exists in this process's pipe buffers. Memory is bounded by
 * the pipe buffers plus rclone's chunk buffer (--dropbox-chunk-size, 48 MiB by
 * default = ~100 MB), independent of the file size. Throughput is bounded by
 * rclone's --bwlimit, which backpressures the whole chain back to the source.
 *
 * `rclone rcat` cannot resume a half-streamed object: a failure restarts that ONE
 * file (idempotent - the planner re-plans from the remote listing, and an
 * unfinished object is never visible under its final name on Dropbox).
 */
import { spawn, execFile } from "node:child_process";
import { createHash } from "node:crypto";
import { PassThrough, Transform, type Readable } from "node:stream";
import { pipeline } from "node:stream/promises";
import { promisify } from "node:util";
import type { RemoteFile } from "./backup-offsite-plan";

const execFileP = promisify(execFile);

export type StreamResult = { plainBytes: number; plainSha256: string; bytes: number; sha256: string };

function hasher() {
  const h = createHash("sha256");
  let n = 0;
  const t = new Transform({
    transform(chunk, _enc, cb) { h.update(chunk); n += chunk.length; cb(null, chunk); },
  });
  return { t, digest: () => ({ bytes: n, sha256: h.digest("hex") }) };
}

export type RcloneOpts = {
  rcloneBin?: string;
  /** extra flags, e.g. from rcloneFlagsFor() */
  flags?: string[];
};

/** Conservative defaults per remote kind. Dropbox is rate-limited per API call, not per byte: few files, one stream, low tps. */
export function rcloneFlagsFor(remote: string, bwlimit?: string): string[] {
  const common = ["--retries", "3", "--low-level-retries", "5", "--stats", "0"];
  const bw = bwlimit ? ["--bwlimit", bwlimit] : [];
  if (remote.startsWith("dropbox:")) {
    return [...common, ...bw, "--transfers", "1", "--checkers", "2", "--tpslimit", "4", "--tpslimit-burst", "4", "--dropbox-chunk-size", "48M", "--dropbox-batch-mode", "sync"];
  }
  return [...common, ...bw, "--transfers", "1", "--tpslimit", "8"];
}

export async function encryptAndUpload(opts: {
  source: Readable;
  /** full rclone destination path incl. file name, e.g. "dropbox:nxeon-backups/2026/2026-10-03/node-2/vms/101-x/....age" */
  dest: string;
  recipientsFile: string;
  ageBin?: string;
} & RcloneOpts): Promise<StreamResult> {
  const age = spawn(opts.ageBin ?? "age", ["-R", opts.recipientsFile], { stdio: ["pipe", "pipe", "pipe"] });
  const rc = spawn(opts.rcloneBin ?? "rclone", ["rcat", opts.dest, ...(opts.flags ?? [])], { stdio: ["pipe", "ignore", "pipe"] });
  let ageErr = "", rcErr = "";
  age.stderr.on("data", (d) => { ageErr = (ageErr + d).slice(-600); });
  rc.stderr.on("data", (d) => { rcErr = (rcErr + d).slice(-600); });
  const exited = (p: typeof age, name: string, err: () => string) =>
    new Promise<void>((resolve, reject) => {
      p.on("error", (e) => reject(new Error(`${name} could not start: ${e.message}`)));
      p.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`${name} exited ${code}: ${err().trim().slice(-300)}`))));
    });
  const ageDone = exited(age, "age", () => ageErr);
  const rcDone = exited(rc as unknown as typeof age, "rclone rcat", () => rcErr);
  const plain = hasher();
  const cipher = hasher();
  const kill = () => { age.kill("SIGKILL"); rc.kill("SIGKILL"); };
  try {
    await Promise.all([
      pipeline(opts.source, plain.t, age.stdin),
      pipeline(age.stdout, cipher.t, rc.stdin),
      ageDone,
      rcDone,
    ]);
  } catch (e) {
    kill();
    // surface the child's own message when it is the root cause
    const root = [ageErr && `age: ${ageErr.trim()}`, rcErr && `rclone: ${rcErr.trim()}`].filter(Boolean).join(" | ");
    throw new Error(`${(e as Error).message}${root ? ` (${root.slice(-300)})` : ""}`);
  }
  const p = plain.digest(), c = cipher.digest();
  return { plainBytes: p.bytes, plainSha256: p.sha256, bytes: c.bytes, sha256: c.sha256 };
}

/** Upload a small plaintext object (manifest.json, README) with rclone rcat. */
export async function rcatText(dest: string, text: string, o: RcloneOpts = {}): Promise<void> {
  const rc = spawn(o.rcloneBin ?? "rclone", ["rcat", dest, ...(o.flags ?? [])], { stdio: ["pipe", "ignore", "pipe"] });
  let err = "";
  rc.stderr.on("data", (d) => { err = (err + d).slice(-400); });
  const done = new Promise<void>((resolve, reject) => {
    rc.on("error", (e) => reject(e));
    rc.on("close", (code) => (code === 0 ? resolve() : reject(new Error(`rclone rcat exited ${code}: ${err.trim()}`))));
  });
  const s = new PassThrough();
  s.end(text);
  await Promise.all([pipeline(s, rc.stdin), done]);
}

/** Read-only listing of everything under `root` (files only), with sizes and mtimes. */
export async function listRemote(root: string, o: RcloneOpts = {}): Promise<RemoteFile[]> {
  const { stdout } = await execFileP(o.rcloneBin ?? "rclone", ["lsjson", "-R", "--files-only", root, "--retries", "3", "--tpslimit", "4"], { maxBuffer: 256 * 2 ** 20, timeout: 20 * 60_000 }).catch((e: any) => {
    // a missing root is an empty listing (first run), anything else is an error
    if (/directory not found|not found/i.test(String(e?.stderr ?? e?.message))) return { stdout: "[]" };
    throw new Error(`rclone lsjson failed: ${String(e?.stderr ?? e?.message).slice(-300)}`);
  });
  const rows = JSON.parse(stdout) as { Path: string; Size: number; ModTime: string }[];
  return rows.map((r) => ({ path: r.Path, size: r.Size, mtimeMs: Date.parse(r.ModTime) || 0 }));
}

/** Delete one object (retention). Never used without an explicit --apply in the CLI. */
export async function deleteRemote(root: string, path: string, o: RcloneOpts = {}): Promise<void> {
  await execFileP(o.rcloneBin ?? "rclone", ["deletefile", `${root}/${path}`, "--retries", "3", "--tpslimit", "4"], { timeout: 5 * 60_000 });
}

/** Total/used bytes of the remote account when the backend reports it (Dropbox does). */
export async function remoteAbout(remote: string, o: RcloneOpts = {}): Promise<{ total: number | null; used: number | null }> {
  try {
    const name = remote.split(":")[0] + ":";
    const { stdout } = await execFileP(o.rcloneBin ?? "rclone", ["about", name, "--json"], { timeout: 60_000 });
    const j = JSON.parse(stdout);
    return { total: typeof j.total === "number" ? j.total : null, used: typeof j.used === "number" ? j.used : null };
  } catch {
    return { total: null, used: null };
  }
}
