    writeFileSync(p("proc", "pressure", "io"), fx.io ?? quiet);
    writeFileSync(p("proc", "pressure", "memory"), fx.mem ?? quiet);
    writeFileSync(p("proc", "loadavg"), fx.load ?? "0.10 0.10 0.10 1/100 1");
    writeFileSync(p("proc", "cpuinfo"), Array.from({ length: fx.cpus ?? 8 }, (_, i) => `processor\t: ${i}\n`).join(""));
    writeFileSync(p("proc", "meminfo"), `MemTotal: 65536000 kB\nMemAvailable: ${(fx.avail ?? 32768) * 1024} kB\nSwapTotal: ${(fx.swapTotal ?? 0) * 1024} kB\nSwapFree: ${(fx.swapFree ?? fx.swapTotal ?? 0) * 1024} kB\n`);
    writeFileSync(p("proc", "vmstat"), fx.vm1 ?? "pswpin 100\npswpout 100\n");
    writeFileSync(p("vm2"), fx.vm2 ?? fx.vm1 ?? "pswpin 100\npswpout 100\n");
