    const r = spawnSync("python3", [GATE, "--proc-root", root, "--sample-seconds", "1", "--vmstat-after", p("vm2"), ...extra], { encoding: "utf8" });
    return { code: r.status, out: JSON.parse(r.stdout || "{}") };
  } finally { rmSync(root, { recursive: true, force: true }); }
}

