  const r = run({});
  assert.equal(r.code, 0);
  assert.equal(r.out.decision, "go");
  assert.equal(r.out.profile, "normal");
});

test("the real node-5 baseline (all PSI ~0, plenty of RAM) is GO/normal", () => {
  const r = run({ avail: 24871, cpus: 12, load: "1.01 0.93 0.88 2/900 1", swapTotal: 2047, swapFree: 2047 });
  assert.equal(r.out.decision, "go");
  assert.equal(r.out.profile, "normal");
});

