  assert.equal(run({ vm1: "pswpin 0\npswpout 0\n", vm2: "pswpin 3000\npswpout 2000\n" }).code, 11);
  assert.equal(run({ vm1: "pswpin 0\npswpout 0\n", vm2: "pswpin 200\npswpout 150\n" }).code, 10);
