  assert.equal(run({ load: "7.50 7.00 6.00 1/1 1", cpus: 8 }).code, 10);
});

test("another heavy job (vzdump / qmrestore / zfs send / rclone) pauses - one job at a time", () => {
  const a = run({ procs: ["/usr/bin/perl /usr/bin/vzdump 100 --mode snapshot"] });
  assert.equal(a.code, 10);
  assert.deepEqual(a.out.metrics.heavyProcesses, ["vzdump"]);
