  assert.equal(run({ procs: ["/usr/bin/zfs list"] }).code, 0, "zfs list is not a heavy job");
  assert.equal(run({ procs: ["rclone rcat x"] }).code, 10);
});

test("thresholds can be tuned with --set and a bad name is a usage error", () => {
  assert.equal(run({ cpu: "some avg10=12.00 avg60=1.00 avg300=1.00 total=1\n" }, ["--set", "cpu_some_avg10_pause=10"]).code, 10);
  const root = mkdtempSync(path.join(tmpdir(), "gate-"));
  const r = spawnSync("python3", [GATE, "--proc-root", root, "--set", "nope=1"], { encoding: "utf8" });
  rmSync(root, { recursive: true, force: true });
  assert.equal(r.status, 2);
});
