cd /tank/nxeon-wt-backups/test; cat > backup-plan.test.ts <<'EOF'
import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

const PLAN = path.resolve(__dirname, "../scripts/backup/nxeon-backup-plan.py");

function plan(vms: unknown[], archives: string[], opts: { state?: unknown; policy?: unknown; now?: string } = {}) {
  const dir = mkdtempSync(path.join(tmpdir(), "plan-"));
  try {
    writeFileSync(path.join(dir, "vms.json"), JSON.stringify(vms));
    for (const a of archives) writeFileSync(path.join(dir, a), "x");
    const args = [PLAN, "--vms-json", path.join(dir, "vms.json"), "--archives-dir", dir, "--policy-file", path.join(dir, "policy.json"), "--now", opts.now ?? "2026-10-03T03:00:00", "--node", "t"];
    if (opts.policy) writeFileSync(path.join(dir, "policy.json"), JSON.stringify(opts.policy));
    if (opts.state) { writeFileSync(path.join(dir, "state.json"), JSON.stringify(opts.state)); args.push("--state-file", path.join(dir, "state.json")); }
    const r = spawnSync("python3", args, { encoding: "utf8" });
    assert.equal(r.status, 0, r.stderr);
    return JSON.parse(r.stdout) as { due: number[]; vms: any[] };
  } finally { rmSync(dir, { recursive: true, force: true }); }
}
const arch = (vmid: number, d: string) => `vzdump-qemu-${vmid}-${d}.vma.zst`;
const vm = (vmid: number, name: string, tags = "nxeon;user-abc", extra: object = {}) => ({ vmid, name, status: "running", tags, ...extra });

test("classes come from tags, templates and the provisioner's <family>-<id> names", () => {
  const p = plan(
    [vm(8000, "nxeon-mail", "nxeon-infra"), vm(600, "valheim-1gcle3"), vm(130, "web-01"), vm(9000, "tpl-ubuntu-2404", "", { template: 1 }), vm(777, "mystery", "")],
    [],
  );
  const cls = Object.fromEntries(p.vms.map((v) => [v.vmid, v.class]));
  assert.deepEqual(cls, { 8000: "infra", 600: "game", 130: "customer-vps", 9000: "template", 777: "infra" });
  // an unaccounted-for guest is treated as precious, and the reason says so
  assert.match(p.vms.find((v) => v.vmid === 777).why, /never under-protected/);
});

test("never-backed-up guests run first within their class; infra before game before template", () => {
  const p = plan(
    [vm(600, "valheim-aaaaaa"), vm(601, "valheim-bbbbbb"), vm(8000, "nxeon-mail", "nxeon-infra"), vm(9000, "tpl-x", "", { template: 1 })],
    [arch(600, "2026_10_01-04_00_00"), arch(8000, "2026_10_01-04_00_00")],
  );
  assert.deepEqual(p.due, [8000, 601, 600]); // infra; then game: never-backed-up 601 before 600 (2 d old); template (never) is due too but last
  assert.equal(p.vms.find((v) => v.vmid === 9000).decision, "due");
});

test("a fresh archive is not due; one at the cadence edge is (a late start must not skip a night)", () => {
  const now = "2026-10-03T03:00:00";
  const p = plan([vm(1, "web-01"), vm(2, "web-01"), vm(3, "web-01")], [
