import { test } from "node:test";
import assert from "node:assert/strict";
import {
  planUploads, planRetention, keepSet, categoryOfSource, indexRemote, projectSteadyState, DEFAULT_PLAN_CONFIG, DEFAULT_RETENTION,
  type NodeInventory, type RemoteFile, type InvVm,
} from "../lib/backup-offsite-plan.ts";

const DAY = 86_400_000;
const NOW = Date.UTC(2026, 9, 3, 12, 0, 0);
const cfg = { ...DEFAULT_PLAN_CONFIG, runDate: "2026-10-03" };
const GiB = 2 ** 30;
const vm = (vmid: number, name: string, cls: string, cad = 7, template = false): InvVm => ({ vmid, name, class: cls, offsiteCadenceDays: cad, template });
const file = (rel: string, size: number, ageDays: number) => ({ rel, size, mtimeMs: NOW - ageDays * DAY });
const vzname = (vmid: number, daysAgo: number) => {
  const d = new Date(NOW - daysAgo * DAY);
  const p = (n: number) => String(n).padStart(2, "0");
  return `vzdump-qemu-${vmid}-${d.getUTCFullYear()}_${p(d.getUTCMonth() + 1)}_${p(d.getUTCDate())}-04_30_00.vma.zst`;
};
const remoteVm = (node: string, vmid: number, slug: string, daysAgo: number): RemoteFile => {
  const n = vzname(vmid, daysAgo);
  const d = new Date(NOW - daysAgo * DAY).toISOString().slice(0, 10);
  return { path: `${d.slice(0, 4)}/${d}/${node}/vms/${vmid}-${slug}/${n}.age`, size: 1, mtimeMs: NOW - daysAgo * DAY };
};

test("categoryOfSource recognises backup artifacts and ignores logs, status files and vm-names", () => {
