  assert.equal(categoryOfSource("nxeon-20261002-031548.sql.gz")?.category, "database");
  assert.equal(categoryOfSource("nxeon_staging-20261002-031548.sql.gz")?.category, "database");
  assert.equal(categoryOfSource("nxeon_agt_x-20261002-031548.sql.gz"), null, "throwaway agent databases are never uploaded");
  assert.equal(categoryOfSource("platform-20261002-031548.tar.gz")?.category, "platform");
  assert.equal(categoryOfSource("status/vm-backup.json"), null);
});

test("the 19-day gap: first run uploads small critical things first and spreads big VMs over nights by budget", () => {
  const inv: NodeInventory[] = [
    {
      node: "primary", via: "local", ok: true,
      vms: [vm(8000, "nxeon-mail", "infra", 1), vm(105, "studionexis-soul", "infra", 1), vm(116, "valheim-4r5fjg", "game"), vm(120, "blue", "game")],
