const vzname = (vmid: number, daysAgo: number) => {
  const d = new Date(NOW - daysAgo * DAY);
  const p = (n: number) => String(n).padStart(2, "0");
  return `vzdump-qemu-${vmid}-${d.getUTCFullYear()}_${p(d.getUTCMonth() + 1)}_${p(d.getUTCDate())}-04_30_00.vma.zst`;
