import { test } from "node:test";
import assert from "node:assert/strict";
import { playerProfile, visitProfile, selectBackupWindow, tzOffsetHours, inWindowUtc, HOURS } from "../lib/backup-window.ts";

const H = 3_600_000;
const DAY = 24 * H;
const NOW = Date.UTC(2026, 9, 3, 12, 0, 0);

/** players online 18:00-23:00 UTC every day for 14 days (an evening-peak node). */
function eveningSessions(days: number, startHour = 18, endHour = 23) {
  const out = [];
  for (let d = 1; d <= days; d++) {
    const day = Date.UTC(2026, 9, 3 - d, 0, 0, 0);
    for (let p = 0; p < 4; p++) out.push({ start: day + startHour * H, end: day + endHour * H });
  }
  return out;
}

test("playerProfile averages concurrent players per UTC hour", () => {
  const p = playerProfile(eveningSessions(14), NOW, 14);
