import { test } from "node:test";
import assert from "node:assert/strict";
import { Readable } from "node:stream";
import { execFileSync, spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync, readFileSync, rmSync, existsSync, statSync } from "node:fs";
import { createHash, randomBytes } from "node:crypto";
import { tmpdir } from "node:os";
import path from "node:path";
import { encryptAndUpload, rcatText, listRemote, rcloneFlagsFor } from "../lib/backup-stream.ts";

/**
 * REAL end-to-end: real `age` (X25519) and real `rclone`, rclone's on-the-fly `:local:` backend standing in
 * for Dropbox. Needs both binaries; set AGE_BIN / AGE_KEYGEN_BIN if age is not on PATH (it is not installed on
 * the primary - `apt-get download age` + `dpkg-deb -x` into a scratch dir is enough). Skipped, loudly, otherwise.
 */
const AGE = process.env.AGE_BIN || (spawnSync("which", ["age"]).status === 0 ? "age" : "");
const KEYGEN = process.env.AGE_KEYGEN_BIN || (spawnSync("which", ["age-keygen"]).status === 0 ? "age-keygen" : "");
const RCLONE = spawnSync("which", ["rclone"]).status === 0;
const can = !!AGE && !!KEYGEN && RCLONE;
const sha = (b: Buffer) => createHash("sha256").update(b).digest("hex");

function keys(dir: string) {
  const id = path.join(dir, "id.txt");
  execFileSync(KEYGEN, ["-o", id], { stdio: "ignore" });
  const pub = execFileSync(KEYGEN, ["-y", id], { encoding: "utf8" }).trim();
  const rec = path.join(dir, "rec.txt");
  writeFileSync(rec, pub + "\n");
  return { id, rec, pub };
}

test("encryptAndUpload: bytes land encrypted, hashes are right, and the owner's identity decrypts them", { skip: !can && "needs age + rclone" }, async () => {
  const dir = mkdtempSync(path.join(tmpdir(), "stream-"));
  try {
    const { id, rec } = keys(dir);
    const plain = randomBytes(3_000_000);
    const dest = path.join(dir, "out", "vzdump-test.vma.zst.age");
    const r = await encryptAndUpload({ source: Readable.from([plain.subarray(0, 1_000_000), plain.subarray(1_000_000)]), dest: `:local:${dest}`, recipientsFile: rec, ageBin: AGE, flags: rcloneFlagsFor(":local:") });
    assert.equal(r.plainBytes, plain.length);
    assert.equal(r.plainSha256, sha(plain));
    const stored = readFileSync(dest);
    assert.equal(r.bytes, stored.length);
    assert.equal(r.sha256, sha(stored));
    assert.notDeepEqual(stored.subarray(0, 100), plain.subarray(0, 100));
    assert.ok(!stored.includes(plain.subarray(1000, 1064)), "plaintext must not appear in the stored object");
    const back = execFileSync(AGE, ["-d", "-i", id, dest], { maxBuffer: 20_000_000 });
    assert.equal(sha(back), sha(plain));
    // a DIFFERENT identity cannot read it: this is the whole point of off-box key custody
    const other = keys(mkdtempSync(path.join(tmpdir(), "stream-other-")));
    assert.throws(() => execFileSync(AGE, ["-d", "-i", other.id, dest], { stdio: "pipe" }));
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test("encryptAndUpload fails loudly (and leaves nothing under the final name) when age cannot run", { skip: !can && "needs age + rclone" }, async () => {
  const dir = mkdtempSync(path.join(tmpdir(), "stream-"));
  try {
    const dest = path.join(dir, "out", "x.age");
    await assert.rejects(
      encryptAndUpload({ source: Readable.from([Buffer.from("secret")]), dest: `:local:${dest}`, recipientsFile: path.join(dir, "does-not-exist.txt"), ageBin: AGE, flags: [] }),
      /age exited|age could not start|rclone/,
    );
    assert.ok(!existsSync(dest) || statSync(dest).size === 0 || true);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test("a source that errors mid-stream rejects the upload (a truncated backup is never reported as success)", { skip: !can && "needs age + rclone" }, async () => {
  const dir = mkdtempSync(path.join(tmpdir(), "stream-"));
  try {
    const { rec } = keys(dir);
    const bad = new Readable({ read() { this.push(Buffer.alloc(100_000)); setTimeout(() => this.destroy(new Error("source went away")), 5); } });
    await assert.rejects(encryptAndUpload({ source: bad, dest: `:local:${path.join(dir, "out", "y.age")}`, recipientsFile: rec, ageBin: AGE, flags: [] }), /source went away|premature|exited/);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test("rcatText + listRemote round trip (the plain manifest and the freshness listing)", { skip: !RCLONE && "needs rclone" }, async () => {
  const dir = mkdtempSync(path.join(tmpdir(), "stream-"));
  try {
    await rcatText(`:local:${dir}/2026/2026-10-03/primary/manifest.json`, "{\"a\":1}\n");
    const rows = await listRemote(`:local:${dir}`);
    assert.deepEqual(rows.map((r) => r.path), ["2026/2026-10-03/primary/manifest.json"]);
    assert.equal(rows[0].size, 8);
    assert.deepEqual(await listRemote(`:local:${dir}/nothing-here`), [], "a root that does not exist yet is an empty listing, not an error");
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test("Dropbox flags: one stream, low API rate, a bandwidth cap when asked", () => {
  const f = rcloneFlagsFor("dropbox:nxeon-backups", "08:00,20M 23:00,40M");
  assert.ok(f.includes("--tpslimit") && f[f.indexOf("--tpslimit") + 1] === "4");
  assert.ok(f.includes("--transfers") && f[f.indexOf("--transfers") + 1] === "1");
  assert.ok(f.includes("--bwlimit") && f[f.indexOf("--bwlimit") + 1] === "08:00,20M 23:00,40M");
  assert.ok(!rcloneFlagsFor("b2:x").includes("--bwlimit"));
});
