import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync, execFileSync } from "node:child_process";
import { mkdtempSync, writeFileSync, readFileSync, rmSync, chmodSync, statSync } from "node:fs";
import { createHash, randomBytes } from "node:crypto";
import { tmpdir } from "node:os";
import path from "node:path";

const SH = path.resolve(__dirname, "../scripts/backup/nxeon-backup-crypt.sh");
const AGE = process.env.AGE_BIN || (spawnSync("which", ["age"]).status === 0 ? "age" : "");
const KEYGEN = process.env.AGE_KEYGEN_BIN || (spawnSync("which", ["age-keygen"]).status === 0 ? "age-keygen" : "");
const can = !!AGE && !!KEYGEN;
const env = (rec: string) => ({ ...process.env, NXEON_BACKUP_RECIPIENTS: rec, AGE_BIN: AGE, AGE_KEYGEN_BIN: KEYGEN });
const sh = (args: string[], rec: string) => spawnSync("bash", [SH, ...args], { encoding: "utf8", env: env(rec) });

test("crypt.sh: keygen -> encrypt -> decrypt round trip with hashes that match", { skip: !can && "needs age" }, () => {
  const dir = mkdtempSync(path.join(tmpdir(), "crypt-"));
  try {
    const id = path.join(dir, "id.txt"), rec = path.join(dir, "rec.txt");
    assert.equal(sh(["keygen", id, rec], rec).status, 0);
    assert.equal(statSync(id).mode & 0o777, 0o600, "the identity file is created private");
    const plain = randomBytes(2_000_000);
    const src = path.join(dir, "a.bin");
    writeFileSync(src, plain);
    const r = sh(["encrypt", src, path.join(dir, "a.bin.age")], rec);
    assert.equal(r.status, 0, r.stderr);
    const meta = JSON.parse(r.stdout.trim().split("\n").pop()!);
    assert.equal(meta.plainBytes, plain.length);
    assert.equal(meta.plainSha256, createHash("sha256").update(plain).digest("hex"));
    const stored = readFileSync(path.join(dir, "a.bin.age"));
    assert.equal(meta.bytes, stored.length);
    assert.equal(meta.sha256, createHash("sha256").update(stored).digest("hex"));
    const d = spawnSync("bash", [SH, "decrypt", path.join(dir, "a.bin.age"), id, path.join(dir, "back.bin")], { encoding: "utf8", env: env(rec) });
    assert.equal(d.status, 0, d.stderr);
    assert.deepEqual(readFileSync(path.join(dir, "back.bin")), plain);
    assert.match(sh(["check"], rec).stderr, /only ONE recipient/, "a single recipient is warned about: escrow key advice");
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test("crypt.sh REFUSES to encrypt with no recipients file (never silently produce a plaintext backup)", () => {
  const dir = mkdtempSync(path.join(tmpdir(), "crypt-"));
  try {
    writeFileSync(path.join(dir, "a"), "x");
    const r = sh(["encrypt", path.join(dir, "a"), path.join(dir, "a.age")], path.join(dir, "missing.txt"));
    assert.notEqual(r.status, 0);
    assert.match(r.stderr, /refusing to produce an UNENCRYPTED backup|age not found/);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test("crypt.sh REFUSES when the recipients file contains a SECRET key (the private key must never live on the box)", { skip: !can && "needs age" }, () => {
  const dir = mkdtempSync(path.join(tmpdir(), "crypt-"));
  try {
    const id = path.join(dir, "id.txt");
    execFileSync(KEYGEN, ["-o", id], { stdio: "ignore" });
    // the identity file holds both the public key comment and the AGE-SECRET-KEY line
    const rec = path.join(dir, "rec.txt");
    writeFileSync(rec, readFileSync(id, "utf8"));
    const r = sh(["check"], rec);
    assert.notEqual(r.status, 0);
    assert.match(r.stderr, /SECRET key/);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test("crypt.sh keygen will not overwrite an existing key", { skip: !can && "needs age" }, () => {
  const dir = mkdtempSync(path.join(tmpdir(), "crypt-"));
  try {
    const id = path.join(dir, "id.txt"), rec = path.join(dir, "rec.txt");
    writeFileSync(id, "precious");
    const r = sh(["keygen", id, rec], rec);
    assert.notEqual(r.status, 0);
    assert.equal(readFileSync(id, "utf8"), "precious");
    chmodSync(id, 0o600);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});
