import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync, spawn } from "node:child_process";
import { mkdtempSync, mkdirSync, writeFileSync, readFileSync, rmSync, existsSync, chmodSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";

/**
 * Drives the real nxeon-backup-node.sh with stub `vzdump`, gate, planner and hypervisor commands, a fake clock
 * (NXEON_BACKUP_NOW) and a throwaway state/status/dest tree. No Proxmox, no guest, nothing real is touched.
 */
const RUNNER = path.resolve(__dirname, "../scripts/backup/nxeon-backup-node.sh");
const WIN_START = Date.UTC(2026, 9, 3, 19, 0, 0) / 1000; // window 19:00 UTC + 4 h

function rig(o: { due?: number[]; gate?: { code: number; profile?: string; reasons?: string[] }; vzdumpExit?: number; vzdumpSleep?: number } = {}) {
  const dir = mkdtempSync(path.join(tmpdir(), "runner-"));
  const bin = path.join(dir, "bin"); mkdirSync(bin);
  const w = (n: string, body: string) => { writeFileSync(path.join(bin, n), `#!/usr/bin/env bash\n${body}\n`); chmodSync(path.join(bin, n), 0o755); return path.join(bin, n); };
  const gate = o.gate ?? { code: 0 };
  w("gate", `echo '${JSON.stringify({ decision: gate.code === 0 ? "go" : gate.code === 10 ? "pause" : "abort", profile: gate.profile ?? "normal", reasons: gate.reasons ?? [] })}'; exit ${gate.code}`);
  const due = o.due ?? [101, 102];
  const vms = due.map((v) => ({ vmid: v, keepLast: 2 }));
  w("plan", `python3 - "$@" <<'PY'
import json,sys
state={}
a=sys.argv[1:]
if "--state-file" in a:
    try: state=json.load(open(a[a.index("--state-file")+1]))
    except Exception: pass
done=set(state.get("done",[]))
due=[v for v in ${JSON.stringify(due)} if v not in done]
print(json.dumps({"due":due,"vms":${JSON.stringify(vms)}}))
PY`);
  w("hyp", `echo hyp >> "${dir}/calls.log"`);
  w("vzdump", `echo "vzdump $*" >> "${dir}/calls.log"; ${o.vzdumpSleep ? `sleep ${o.vzdumpSleep};` : ""} exit ${o.vzdumpExit ?? 0}`);
  const env = (now: number, extra: Record<string, string> = {}) => ({
    PATH: process.env.PATH!, HOME: dir,
    NXEON_BACKUP_CONF: path.join(dir, "none.env"), NXEON_BACKUP_V2: "1",
    NXEON_BACKUP_STATE_DIR: path.join(dir, "state"), NXEON_BACKUP_STATUS_DIR: path.join(dir, "status"),
    NXEON_PLATFORM_BACKUP_DIR: path.join(dir, "dest"), NXEON_BACKUP_WINDOW_FILE: path.join(dir, "no-window.json"),
    NXEON_BACKUP_WINDOW_START_UTC: "19:00", NXEON_BACKUP_WINDOW_HOURS: "4",
    NXEON_BACKUP_GATE_CMD: path.join(bin, "gate"), NXEON_BACKUP_PLAN_CMD: path.join(bin, "plan"), NXEON_BACKUP_HYPERVISOR_CMD: path.join(bin, "hyp"),
    NXEON_BACKUP_VZDUMP_BIN: path.join(bin, "vzdump"), NXEON_BACKUP_LOCK: path.join(dir, "lock"),
    NXEON_BACKUP_NOW: String(now), NXEON_BACKUP_COOLDOWN_S: "0", NXEON_BACKUP_PAUSE_POLL_S: "1", NXEON_BACKUP_PAUSE_MAX_MIN: "0",
    ...extra,
  });
  const run = (now: number, extra: Record<string, string> = {}, args: string[] = []) => spawnSync("bash", [RUNNER, ...args], { encoding: "utf8", env: env(now, extra) });
  const calls = () => (existsSync(path.join(dir, "calls.log")) ? readFileSync(path.join(dir, "calls.log"), "utf8").trim().split("\n") : []);
  const status = () => JSON.parse(readFileSync(path.join(dir, "status", "backup-run.json"), "utf8"));
  return { dir, run, calls, status, clean: () => rmSync(dir, { recursive: true, force: true }), env };
}

test("INERT unless NXEON_BACKUP_V2=1: shipping the script changes nothing", () => {
  const r = rig();
  try {
    const out = r.run(WIN_START + 600, { NXEON_BACKUP_V2: "0" });
    assert.equal(out.status, 0);
    assert.match(out.stdout, /inert/);
    assert.deepEqual(r.calls(), []);
  } finally { r.clean(); }
});

test("outside the window: exit 0, silent, nothing runs (the timer ticks every 15 min)", () => {
  const r = rig();
  try {
    const out = r.run(WIN_START - 3600);   // 18:00
    assert.equal(out.status, 0);
    assert.equal(out.stdout.trim(), "");
    assert.deepEqual(r.calls(), []);
    assert.equal(r.run(WIN_START + 4 * 3600 + 5).stdout.trim(), "", "just after the window closes");
  } finally { r.clean(); }
});

test("inside the window: hypervisor snapshot once, then each due guest in plan order, snapshot mode, throttled", () => {
  const r = rig({ due: [8000, 600, 601] });
  try {
    const out = r.run(WIN_START + 600);
    assert.equal(out.status, 0, out.stdout + out.stderr);
    const c = r.calls();
    assert.equal(c[0], "hyp");
    assert.match(c[1], /^vzdump 8000 --mode snapshot --compress zstd --zstd 1 --bwlimit 61440 --ionice 7 --performance max-workers=1/);
    assert.match(c[1], /--prune-backups keep-last=2/);
    assert.deepEqual(c.slice(2).map((x) => x.split(" ")[1]), ["600", "601"]);
    assert.equal(r.status().state, "complete");
    assert.deepEqual(r.status().done, [8000, 600, 601]);
    // the next 15-minute tick finds nothing to do and does NOT repeat the snapshot or any guest
    const again = r.run(WIN_START + 1500);
    assert.equal(again.status, 0);
    assert.equal(r.calls().length, 4);
    assert.match(again.stdout, /nothing due tonight/);
  } finally { r.clean(); }
});

test("a starved node (gate profile 'gentle') backs up at the low bandwidth cap", () => {
  const r = rig({ due: [101], gate: { code: 0, profile: "gentle" } });
  try {
    r.run(WIN_START + 600);
    assert.match(r.calls().find((x) => x.startsWith("vzdump"))!, /--bwlimit 20480/);
  } finally { r.clean(); }
});

test("gate says PAUSE past the budget: nothing is backed up, the run is 'deferred' (exit 0, resumes next tick)", () => {
  const r = rig({ gate: { code: 10, reasons: ["cpu PSI some avg10 55 >= 30"] } });
  try {
    const out = r.run(WIN_START + 600);
    assert.equal(out.status, 0);
    assert.deepEqual(r.calls(), [], "not even the hypervisor snapshot runs on a busy node");
    assert.equal(r.status().state, "deferred");
    assert.match(out.stdout, /stayed busy|busy/);
  } finally { r.clean(); }
});

test("gate says ABORT: no work tonight", () => {
  const r = rig({ gate: { code: 11, reasons: ["memory PSI full avg10 2.5"] } });
  try {
    const out = r.run(WIN_START + 600);
    assert.equal(out.status, 0);
    assert.deepEqual(r.calls(), []);
    assert.match(out.stdout, /ABORT/);
  } finally { r.clean(); }
});

test("a gate that cannot answer blocks the backup: never back up blind", () => {
  const r = rig({ gate: { code: 3 } });
  try {
    r.run(WIN_START + 600);
    assert.deepEqual(r.calls(), []);
  } finally { r.clean(); }
});

test("HARD STOP at the window's end: the running vzdump is terminated and the guest is deferred to the next window", () => {
  const r = rig({ due: [101, 102], vzdumpSleep: 30 });
  try {
    const t0 = Date.now();
    // 2 s before the window closes, no safety margin: vzdump starts, then `timeout` kills it at the deadline
    const out = r.run(WIN_START + 4 * 3600 - 2, { NXEON_BACKUP_MIN_ITEM_MARGIN_MIN: "0" });
    assert.ok(Date.now() - t0 < 15_000, "the 30 s vzdump must not be allowed to run past the window");
    assert.equal(out.status, 0, out.stdout);
    assert.equal(r.status().state, "deferred");
    assert.deepEqual(r.status().deferred, [101, 102]);
    assert.deepEqual(r.status().done, []);
    assert.equal(r.calls().filter((x) => x.startsWith("vzdump")).length, 1, "the second guest is not even started once the window is over");
  } finally { r.clean(); }
});

test("with less than the safety margin left, no new guest is started", () => {
  const r = rig({ due: [101] });
  try {
    r.run(WIN_START + 4 * 3600 - 300, { NXEON_BACKUP_MIN_ITEM_MARGIN_MIN: "10" });
    assert.equal(r.calls().filter((x) => x.startsWith("vzdump")).length, 0);
  } finally { r.clean(); }
});

test("a failing vzdump makes the unit FAIL (exit 1 -> OnFailure alert) but the other guests still run", () => {
  const r = rig({ due: [101, 102], vzdumpExit: 1 });
  try {
    const out = r.run(WIN_START + 600);
    assert.equal(out.status, 1);
    assert.equal(r.calls().filter((x) => x.startsWith("vzdump")).length, 2);
    assert.equal(r.status().state, "failed");
    assert.deepEqual(r.status().failed, [101, 102]);
  } finally { r.clean(); }
});

test("only one backup job per node: a held lock makes the runner stand down", () => {
  const r = rig();
  try {
    const lock = path.join(r.dir, "lock");
    const holder = spawn("bash", ["-c", `exec 9>${lock}; flock 9; sleep 5`]);
    // wait for the holder to own the lock
    const t = Date.now(); while (Date.now() - t < 800) { /* spin briefly */ }
    const out = r.run(WIN_START + 600);
    holder.kill();
    assert.equal(out.status, 0);
    assert.match(out.stdout, /another backup job/);
    assert.deepEqual(r.calls(), []);
  } finally { r.clean(); }
});

test("the window may cross midnight (start 23:00 + 4 h): 01:00 is inside, and belongs to yesterday's window-day", () => {
