export async function agentBackupHealth(node: AgentNode): Promise<unknown> {
  return agentRequest(node, "GET", "/v1/backup/health");
}

/** Open one backup file (a path from the node's manifest) as a stream, for the off-site uploader. */
export async function agentBackupFileStream(node: AgentNode, relPath: string): Promise<import("node:stream").Readable> {
  const token = agentAuthOrThrow(node);
  const url = `https://${node.publicIp}:${node.agentPort}/v1/backup/file?path=${encodeURIComponent(relPath)}`;
  let res: Awaited<ReturnType<typeof undiciFetch>>;
  try {
    res = await undiciFetch(url, { method: "GET", headers: { Authorization: `Bearer ${token}` }, dispatcher: insecureAgent, signal: undefined });
  } catch (e: any) {
    throw new NodeAgentError(`could not reach node-agent on "${node.name}" for ${relPath}: ${e?.message ?? e}`, node.name);
  }
  if (!res.ok || !res.body) {
    const text = await res.text().catch(() => "");
    throw new NodeAgentError(`node-agent on "${node.name}" returned ${res.status} for ${relPath}: ${text.slice(0, 300)}`, node.name);
  }
  const { Readable } = await import("node:stream");
  return Readable.fromWeb(res.body as any);
}
