cat > lib/backup-node-health.ts <<'EOF'
/**
 * Node backup-health: the wire type of the node-agent's GET /v1/backup/health, a local collector for the
 * primary (which runs no agent), and the pure converters into the shapes the freshness evaluator and the
 * upload planner consume. READ-ONLY: only `systemctl show`, `pvesh get` (list), `pveversion`, file reads.
 */
import { execFile } from "node:child_process";
import { promises as fs } from "node:fs";
import path from "node:path";
import { promisify } from "node:util";
import type { NodeHealth, VmInfo, TimerState } from "./backup-freshness";
import type { InvFile, InvVm, NodeInventory } from "./backup-offsite-plan";

const execFileP = promisify(execFile);

export type PlanVm = { vmid: number; name: string | null; class: string; localCadenceDays: number; offsiteCadenceDays: number; keepLast: number };
export type AgentBackupHealth = {
  node: string;
  at: number;
  kernel?: string;
  pveversion?: string | null;
  timers: TimerState[];
  vmsOk: boolean;
  vms: { vmid: number; name: string; status: string; template: number; tags: string; maxdisk: number }[];
  plan: { vms: PlanVm[] } | null;
  newestArchiveByVmid: Record<string, number>;
  largestArchiveBytes: number;
  hypervisorNewestMs: number | null;
  backupFs: { freeBytes: number; totalBytes: number } | null;
  runStatus: { state?: string; ok?: boolean } | null;
};

/** Strict fallback when a node has no planner: templates are templates, everything else is treated as precious. */
function classOf(h: AgentBackupHealth, v: AgentBackupHealth["vms"][number]): { cls: string; local: number; off: number } {
  const p = h.plan?.vms.find((x) => x.vmid === v.vmid);
  if (p) return { cls: p.class, local: p.localCadenceDays, off: p.offsiteCadenceDays };
  if (v.template) return { cls: "template", local: 7, off: 30 };
  return { cls: "infra", local: 1, off: 1 };
}

export function toNodeHealth(h: AgentBackupHealth, node: string, nodeId: string): NodeHealth {
  const vms: VmInfo[] = h.vms.map((v) => {
    const c = classOf(h, v);
    return { vmid: v.vmid, name: v.name, class: c.cls, template: !!v.template, offsiteCadenceDays: c.off, localCadenceDays: c.local, localNewestMs: h.newestArchiveByVmid[String(v.vmid)] ?? null };
  });
  return { node, nodeId, reachable: true, timers: h.timers, vms, hypervisorNewestMs: h.hypervisorNewestMs, backupFs: h.backupFs, largestArchiveBytes: h.largestArchiveBytes || null };
}

export function unreachable(node: string, nodeId: string, error: string): NodeHealth {
  return { node, nodeId, reachable: false, error, timers: [], vms: [], hypervisorNewestMs: null, backupFs: null, largestArchiveBytes: null };
}

export function toInventoryVms(h: AgentBackupHealth): InvVm[] {
  return h.vms.map((v) => {
    const c = classOf(h, v);
    return { vmid: v.vmid, name: v.name, class: c.cls, offsiteCadenceDays: c.off, template: !!v.template };
  });
}

/** A node's own platform + hypervisor files as planner inputs (from the agent's /v1/backup/manifest entries). */
export function toInventory(node: string, via: "local" | "agent", h: AgentBackupHealth | null, files: InvFile[]): NodeInventory {
  if (!h || !h.vmsOk) return { node, via, ok: false, vms: [], files: [] };
  return { node, via, ok: true, vms: toInventoryVms(h), files };
}

const sh = async (cmd: string, args: string[], t = 30_000) => {
  try { return (await execFileP(cmd, args, { timeout: t, maxBuffer: 8 * 2 ** 20 })).stdout; } catch { return null; }
};

/** Same payload the agent returns, collected on the primary itself. */
export async function collectLocalHealth(root = process.env.NXEON_BACKUP_ROOT ?? "/tank/backup", planScript = path.join(process.cwd(), "scripts/backup/nxeon-backup-plan.py")): Promise<AgentBackupHealth> {
  const timers: TimerState[] = [];
  for (const unit of ["nxeon-backup-run.timer", "nxeon-backup-vms.timer"]) {
    const t = await sh("systemctl", ["show", unit, "-p", "LoadState,UnitFileState,ActiveState,LastTriggerUSec"], 8000);
    if (!t) continue;
    const kv: Record<string, string> = {};
    for (const l of t.split("\n")) { const i = l.indexOf("="); if (i > 0) kv[l.slice(0, i)] = l.slice(i + 1); }
    if (kv.LoadState === "not-found") continue;
    const last = Date.parse(kv.LastTriggerUSec ?? "");
    timers.push({ name: unit, enabled: ["enabled", "enabled-runtime", "static"].includes(kv.UnitFileState), active: kv.ActiveState === "active", lastTriggerMs: Number.isFinite(last) ? last : null });
  }
  let vms: AgentBackupHealth["vms"] = [];
  let vmsOk = false;
  const vj = await sh("pvesh", ["get", "/nodes/localhost/qemu", "--output-format", "json"]);
  if (vj) { try { vms = (JSON.parse(vj) as any[]).map((v) => ({ vmid: v.vmid, name: v.name ?? "", status: v.status ?? "", template: v.template ? 1 : 0, tags: v.tags ?? "", maxdisk: v.maxdisk ?? 0 })); vmsOk = true; } catch { /* unreliable */ } }
  const newest: Record<string, number> = {};
  let largest = 0;
  let hyp: number | null = null;
  try {
    for (const name of await fs.readdir(path.join(root, "platform"))) {
      const m = /^vzdump-qemu-(\d+)-(\d{4})_(\d{2})_(\d{2})-(\d{2})_(\d{2})_(\d{2})\.vma(\.zst|\.gz|\.lzo)?$/.exec(name);
      const h = /^host-config-(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})(\d{2})\.tar\.gz$/.exec(name);
      if (m) {
        const ts = Date.UTC(+m[2], +m[3] - 1, +m[4], +m[5], +m[6], +m[7]);
        if (!newest[m[1]] || ts > newest[m[1]]) newest[m[1]] = ts;
        const st = await fs.stat(path.join(root, "platform", name)).catch(() => null);
        if (st && st.size > largest) largest = st.size;
      } else if (h) {
        const ts = Date.UTC(+h[1], +h[2] - 1, +h[3], +h[4], +h[5], +h[6]);
        if (hyp === null || ts > hyp) hyp = ts;
      }
    }
    for (const name of await fs.readdir(path.join(root, "hypervisor")).catch(() => [] as string[])) {
      const h = /^hypervisor-.*-(\d{4})(\d{2})(\d{2})-(\d{2})(\d{2})(\d{2})\.tar\.gz$/.exec(name);
      if (h) { const ts = Date.UTC(+h[1], +h[2] - 1, +h[3], +h[4], +h[5], +h[6]); if (hyp === null || ts > hyp) hyp = ts; }
    }
  } catch { /* no dirs yet */ }
  let backupFs: AgentBackupHealth["backupFs"] = null;
  try { const st = await fs.statfs(root); backupFs = { freeBytes: Number(st.bavail) * Number(st.bsize), totalBytes: Number(st.blocks) * Number(st.bsize) }; } catch { /* missing */ }
  let plan: AgentBackupHealth["plan"] = null;
  const pj = await sh("python3", [planScript, "--archives-dir", path.join(root, "platform"), "--policy-file", "/etc/nxeon/backup-policy.json"], 60_000);
  if (pj) { try { plan = JSON.parse(pj); } catch { plan = null; } }
  let runStatus = null;
  try { runStatus = JSON.parse(await fs.readFile(path.join(root, "status", "backup-run.json"), "utf8")); } catch { /* none */ }
  return { node: "primary", at: Date.now(), timers, vmsOk, vms, plan, newestArchiveByVmid: newest, largestArchiveBytes: largest, hypervisorNewestMs: hyp, backupFs, runStatus };
}
