/**
 * Pure bookkeeping for one uploader run: turn completed uploads into per-(date,node) manifests, merging with a
 * manifest left by an earlier partial run of the same night (a resumed run must ADD to it, never replace it).
 */
import { buildManifest, runDir, validateManifest, type Manifest, type ManifestItem } from "./backup-layout";
import type { UploadTask } from "./backup-offsite-plan";
import type { StreamResult } from "./backup-stream";

export type UploadResult = { task: UploadTask; result: StreamResult; startedAt: string; finishedAt: string };

export function itemFromResult(r: UploadResult, date: string): Omit<ManifestItem, "restore"> {
  const dir = runDir(date, r.task.node);
  return {
    category: r.task.category,
    path: r.task.remote.slice(dir.length + 1),
    plainName: r.task.plainName,
    ...(r.task.vmid ? { vmid: r.task.vmid, vmName: r.task.vmName } : {}),
    ...(r.task.vmClass ? { class: r.task.vmClass } : {}),
    bytes: r.result.bytes,
    sha256: r.result.sha256,
    plainBytes: r.result.plainBytes,
    plainSha256: r.result.plainSha256,
    sourceAt: new Date(r.task.mtimeMs).toISOString(),
  };
}

/** One manifest per node for this run date. `existing` = manifests already on the remote for the same date/node. */
export function buildRunManifests(
  results: readonly UploadResult[],
  date: string,
  recipients: string[],
  existing: ReadonlyMap<string, Manifest> = new Map(),
  extra: { nxeonCommit?: string; hosts?: ReadonlyMap<string, Manifest["run"]["host"]> } = {},
): Map<string, Manifest> {
  const byNode = new Map<string, UploadResult[]>();
  for (const r of results) (byNode.get(r.task.node) ?? byNode.set(r.task.node, []).get(r.task.node)!).push(r);
  const out = new Map<string, Manifest>();
  for (const [node, rs] of byNode) {
    const prev = existing.get(node);
    const items = new Map<string, Omit<ManifestItem, "restore">>();
    for (const i of prev?.items ?? []) { const { restore: _r, ...rest } = i; items.set(i.path, rest); }
    for (const r of rs) { const it = itemFromResult(r, date); items.set(it.path, it); }
    const m = buildManifest({
      date, node,
      startedAt: prev?.run.startedAt ?? rs.map((r) => r.startedAt).sort()[0],
      finishedAt: rs.map((r) => r.finishedAt).sort().slice(-1)[0],
      items: [...items.values()],
      recipients,
      host: extra.hosts?.get(node),
      nxeonCommit: extra.nxeonCommit,
    });
    const problems = validateManifest(m);
    if (problems.length) throw new Error(`manifest for ${node} ${date} is invalid: ${problems.join("; ")}`);
    out.set(node, m);
  }
  return out;
}
EOF
cat > scripts/backup-offsite-run.ts <<'EOF'
/**
 * Off-site uploader (v2): plans what is not yet off-site, and (only when told to) streams it, encrypted, to the remote.
 *
 *   npx tsx scripts/backup-offsite-run.ts                    PLAN ONLY (default). Reads local state, the node-agents
 *                                                            (read-only GETs) and the remote listing. Changes nothing.
 *   npx tsx scripts/backup-offsite-run.ts --execute          upload. Requires NXEON_OFFSITE_V2=1, a valid recipients
 *                                                            file and a "go" from the pre-flight gate.
 *   ... --retention                                          also print the retention plan (deletions) - still read-only
 *   ... --execute --apply-retention                          also delete what the retention plan lists (capped)
 *   ... --inventory-file f.json                              TEST/DRY: take inventories + remote listing from a JSON file
 *                                                            instead of the DB/agents/rclone (shape: {runDate, nodes, remote})
 *
 * Strictly sequential: one file at a time, nice'd by its systemd unit, bandwidth-capped by rclone --bwlimit
 * (NXEON_OFFSITE_BWLIMIT, a rclone timetable like "08:00,10M 23:00,30M"). Before every file the gate is asked; busy
 * pauses (bounded), abort stops. Encryption is mandatory: with no recipients file nothing is uploaded.
 */
import { createReadStream, promises as fs } from "node:fs";
import { execFile, spawnSync } from "node:child_process";
import path from "node:path";
import { promisify } from "node:util";
import { planUploads, planRetention, DEFAULT_PLAN_CONFIG, type InvFile, type NodeInventory, type RemoteFile, type InvVm } from "../lib/backup-offsite-plan";
import { OFFSITE_ROOT_DEFAULT, ROOT_README, renderRunReadme, runDir, type Manifest } from "../lib/backup-layout";
import { buildRunManifests, type UploadResult } from "../lib/backup-upload-run";
import { encryptAndUpload, rcatText, listRemote, deleteRemote, rcloneFlagsFor, remoteAbout } from "../lib/backup-stream";
import { collectLocalHealth, toInventory, type AgentBackupHealth } from "../lib/backup-node-health";

const execFileP = promisify(execFile);
const args = new Set(process.argv.slice(2));
const argVal = (n: string) => { const i = process.argv.indexOf(n); return i > 0 ? process.argv[i + 1] : undefined; };
const EXECUTE = args.has("--execute");
const REMOTE = process.env.OFFSITE_RCLONE_REMOTE || `dropbox:${OFFSITE_ROOT_DEFAULT}`;
const ROOT = process.env.NXEON_BACKUP_ROOT || "/tank/backup";
const STATUS = path.join(process.env.NXEON_BACKUP_STATUS_DIR || "/tank/backup/status", "offsite.json");
const RECIPIENTS = process.env.NXEON_BACKUP_RECIPIENTS || "/etc/nxeon/backup-recipients.txt";
const BWLIMIT = process.env.NXEON_OFFSITE_BWLIMIT || "15M";
const PRIMARY = process.env.NXEON_PRIMARY_NODE_NAME || "primary";
const HERE = path.dirname(new URL(import.meta.url).pathname);
const GATE = path.join(HERE, "backup/nxeon-backup-gate.py");
const log = (m: string) => console.log(`[${new Date().toISOString()}] ${m}`);

type Source = { node: string; via: "local" | "agent"; open: (rel: string) => Promise<NodeJS.ReadableStream> };

async function localFiles(): Promise<InvFile[]> {
  const out: InvFile[] = [];
  for (const sub of ["platform", "hypervisor", "db", "platform-extra"]) {
    for (const name of await fs.readdir(path.join(ROOT, sub)).catch(() => [] as string[])) {
      const st = await fs.stat(path.join(ROOT, sub, name)).catch(() => null);
      if (st?.isFile()) out.push({ rel: `${sub}/${name}`, size: st.size, mtimeMs: st.mtimeMs });
    }
  }
  return out;
}

async function gather(): Promise<{ runDate: string; inv: NodeInventory[]; sources: Map<string, Source>; remote: RemoteFile[]; hosts: Map<string, Manifest["run"]["host"]> }> {
  const sources = new Map<string, Source>();
  const hosts = new Map<string, Manifest["run"]["host"]>();
  const invFile = argVal("--inventory-file");
  if (invFile) {
    const j = JSON.parse(await fs.readFile(invFile, "utf8")) as { runDate: string; nodes: NodeInventory[]; remote: RemoteFile[] };
    return { runDate: j.runDate, inv: j.nodes, sources, remote: j.remote, hosts };
  }
  const inv: NodeInventory[] = [];
  const lh = await collectLocalHealth(ROOT);
  inv.push(toInventory(PRIMARY, "local", lh, await localFiles()));
  sources.set(PRIMARY, { node: PRIMARY, via: "local", open: async (rel) => createReadStream(path.join(ROOT, rel)) });
  hosts.set(PRIMARY, { hostname: lh.node, pveVersion: lh.pveversion ?? undefined, kernel: lh.kernel });
  const { db } = await import("../lib/db");
  const { agentBackupHealth, agentBackupManifest, agentBackupFileStream } = await import("../lib/node-agent");
  const nodes = await db.node.findMany({ where: { isPrimary: false, enabled: true }, select: { id: true, name: true, publicIp: true, agentPort: true, agentTokenEnc: true } });
  for (const n of nodes) {
    try {
      const h = (await agentBackupHealth(n)) as AgentBackupHealth;
      const entries = await agentBackupManifest(n);
      inv.push(toInventory(n.name, "agent", h, entries.map((e) => ({ rel: e.path, size: e.size, mtimeMs: e.mtimeMs }))));
      sources.set(n.name, { node: n.name, via: "agent", open: (rel) => agentBackupFileStream(n, rel) });
      hosts.set(n.name, { hostname: h.node, pveVersion: h.pveversion ?? undefined, kernel: h.kernel });
    } catch (e: any) {
      log(`node ${n.name}: agent unreadable (${String(e?.message ?? e).slice(0, 160)}) - nothing planned for it`);
      inv.push({ node: n.name, via: "agent", ok: false, vms: [], files: [] });
    }
  }
  const remote = await listRemote(REMOTE);
  return { runDate: new Date().toISOString().slice(0, 10), inv, sources, remote, hosts };
}

function gateDecision(): "go" | "pause" | "abort" {
  const r = spawnSync("python3", [GATE, "--sample-seconds", "3"], { encoding: "utf8" });
  return r.status === 0 ? "go" : r.status === 10 ? "pause" : "abort";
}

async function readRecipients(): Promise<string[]> {
  const txt = await fs.readFile(RECIPIENTS, "utf8").catch(() => "");
  if (/AGE-SECRET-KEY/.test(txt)) throw new Error(`${RECIPIENTS} contains a SECRET key - refusing`);
  const keys = txt.split("\n").map((l) => l.trim()).filter((l) => /^age1[a-z0-9]+$/.test(l));
  if (!keys.length) throw new Error(`no age recipients in ${RECIPIENTS} - refusing to upload unencrypted`);
  return keys;
}

async function writeStatus(s: Record<string, unknown>) {
  let last: unknown = null;
  try { last = JSON.parse(await fs.readFile(STATUS, "utf8")).lastSuccessAt ?? null; } catch { /* first run */ }
  const body = { configured: true, kind: "rclone", at: new Date().toISOString(), lastSuccessAt: s.ok ? new Date().toISOString() : last, ...s };
  await fs.mkdir(path.dirname(STATUS), { recursive: true });
  await fs.writeFile(STATUS + ".tmp", JSON.stringify(body) + "\n");
  await fs.rename(STATUS + ".tmp", STATUS);
}

async function main() {
  const g = await gather();
  const cfg = { ...DEFAULT_PLAN_CONFIG, runDate: g.runDate, templateNode: PRIMARY, byteBudget: Number(process.env.NXEON_OFFSITE_BYTE_BUDGET || DEFAULT_PLAN_CONFIG.byteBudget) };
  const plan = planUploads(g.inv, g.remote, Date.now(), cfg);
  log(`${EXECUTE ? "EXECUTE" : "PLAN ONLY"}: ${plan.tasks.length} upload(s), ${(plan.bytes / 2 ** 30).toFixed(1)} GiB, ${plan.deferred.length} deferred (budget), ${plan.skipped.length} skipped`);
  for (const t of plan.tasks) console.log(`  + ${t.node} ${t.category}${t.vmid ? ` ${t.vmid} ${t.vmName}` : ""}  ${(t.size / 2 ** 20).toFixed(0)} MiB  -> ${t.remote}\n      ${t.reason}`);
  for (const t of plan.deferred) console.log(`  ~ deferred ${t.node} ${t.category} ${t.vmid ?? ""} ${(t.size / 2 ** 30).toFixed(1)} GiB`);
  if (args.has("--verbose")) for (const s of plan.skipped) console.log(`  - skip ${s.node} ${s.rel}: ${s.why}`);

  let retention: ReturnType<typeof planRetention> | null = null;
  if (args.has("--retention") || args.has("--apply-retention")) {
    const vmsByNode = new Map<string, Map<number, InvVm>>(g.inv.map((n) => [n.node, new Map(n.vms.map((v) => [v.vmid, v]))]));
    retention = planRetention(g.remote, vmsByNode, new Set(g.inv.filter((n) => n.ok).map((n) => n.node)), Date.now());
    log(`retention: keep ${retention.keep}, delete ${retention.delete.length}${retention.capped ? " (capped)" : ""}`);
    for (const d of retention.delete.slice(0, 50)) console.log(`  x ${d.path}  (${d.why})`);
  }
  if (!EXECUTE) return;

  if (process.env.NXEON_OFFSITE_V2 !== "1") { log("NXEON_OFFSITE_V2 is not 1 - refusing to upload (plan above is all this run does)"); process.exit(0); }
  const recipients = await readRecipients().catch(async (e) => { await writeStatus({ ok: false, encrypted: false, detail: String(e.message) }); throw e; });
  const flags = rcloneFlagsFor(REMOTE, BWLIMIT);
  const results: UploadResult[] = [];
  let failed = 0;
  let stopped = "";
  for (const t of plan.tasks) {
    let d = gateDecision();
    for (let waited = 0; d === "pause" && waited < 30 * 60; waited += 60) { await new Promise((r) => setTimeout(r, 60_000)); d = gateDecision(); }
    if (d !== "go") { stopped = `gate said ${d}`; log(`gate: ${d} - stopping; the rest resumes on the next run`); break; }
    const src = g.sources.get(t.node);
    if (!src) { log(`no source for ${t.node}`); failed++; continue; }
    const startedAt = new Date().toISOString();
    try {
      log(`uploading ${t.node} ${t.rel} (${(t.size / 2 ** 20).toFixed(0)} MiB)`);
      const stream = await src.open(t.rel);
      const result = await encryptAndUpload({ source: stream as any, dest: `${REMOTE}/${t.remote}`, recipientsFile: RECIPIENTS, flags });
      results.push({ task: t, result, startedAt, finishedAt: new Date().toISOString() });
    } catch (e: any) { failed++; log(`FAILED ${t.rel}: ${String(e?.message ?? e).slice(0, 300)}`); }
  }

  if (results.length) {
    const existing = new Map<string, Manifest>();
    const nodes = new Set(results.map((r) => r.task.node));
    for (const node of nodes) {
      try { const { stdout } = await execFileP("rclone", ["cat", `${REMOTE}/${runDir(g.runDate, node)}/manifest.json`], { maxBuffer: 64 * 2 ** 20 }); existing.set(node, JSON.parse(stdout)); } catch { /* none yet */ }
    }
    let commit: string | undefined;
    try { commit = (await execFileP("git", ["rev-parse", "--short", "HEAD"], { cwd: path.join(HERE, "..") })).stdout.trim(); } catch { /* no git */ }
    const manifests = buildRunManifests(results, g.runDate, recipients, existing, { nxeonCommit: commit, hosts: g.hosts });
    for (const [node, m] of manifests) {
      await rcatText(`${REMOTE}/${runDir(g.runDate, node)}/manifest.json`, JSON.stringify(m, null, 2) + "\n", { flags: [] });
      await rcatText(`${REMOTE}/${runDir(g.runDate, node)}/README.txt`, renderRunReadme(m), { flags: [] });
    }
    if (!g.remote.some((f) => f.path === "README.txt")) await rcatText(`${REMOTE}/README.txt`, ROOT_README, { flags: [] }).catch(() => undefined);
  }

  if (args.has("--apply-retention") && retention && !failed) {
    for (const d of retention.delete) { try { await deleteRemote(REMOTE, d.path); } catch (e: any) { log(`WARN could not delete ${d.path}: ${e?.message}`); } }
  }
  const about = await remoteAbout(REMOTE);
  const bytes = results.reduce((s, r) => s + r.result.bytes, 0);
  const ok = failed === 0 && !stopped;
  await writeStatus({ ok, encrypted: true, recipients: recipients.length, uploaded: results.length, bytes, failed, deferred: plan.deferred.length, detail: ok ? `uploaded ${results.length} item(s)` : `${failed} failed${stopped ? `; ${stopped}` : ""}`, usedBytes: about.used, totalBytes: about.total });
  log(`done: ${results.length} uploaded, ${failed} failed${stopped ? `, stopped (${stopped})` : ""}`);
  process.exit(failed ? 1 : 0);
}

main().catch((e) => { console.error("[backup-offsite-run] fatal:", e); process.exit(1); });
EOF
