import { test } from "node:test";
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { buildRunManifests, type UploadResult } from "../lib/backup-upload-run.ts";
import { validateManifest } from "../lib/backup-layout.ts";

const SHA = "b".repeat(64);
const res = (node: string, rel: string, remote: string, over: object = {}): UploadResult => ({
  task: { category: "vm", node, via: "agent", rel, plainName: rel.split("/").pop()!, vmid: 141, vmName: "palworld", vmClass: "game", size: 10, mtimeMs: Date.UTC(2026, 9, 2), remote, reason: "x", ...over } as any,
  result: { bytes: 100, sha256: SHA, plainBytes: 120, plainSha256: SHA },
  startedAt: "2026-10-04T01:00:00Z", finishedAt: "2026-10-04T01:10:00Z",
});

test("one manifest per node; paths are relative to the run folder; valid", () => {
  const m = buildRunManifests([res("node-2", "platform/vzdump-qemu-141-2026_10_02-04_47_50.vma.zst", "2026/2026-10-04/node-2/vms/141-palworld/vzdump-qemu-141-2026_10_02-04_47_50.vma.zst.age")], "2026-10-04", ["age1abc"]);
  const man = m.get("node-2")!;
  assert.equal(man.items[0].path, "vms/141-palworld/vzdump-qemu-141-2026_10_02-04_47_50.vma.zst.age");
  assert.equal(man.items[0].class, "game");
  assert.deepEqual(validateManifest(man), []);
});

test("a resumed run ADDS to the earlier manifest of the same night instead of replacing it", () => {
  const first = buildRunManifests([res("node-2", "platform/a.vma.zst", "2026/2026-10-04/node-2/vms/141-palworld/vzdump-qemu-141-2026_10_02-04_47_50.vma.zst.age")], "2026-10-04", ["age1abc"]).get("node-2")!;
  const second = buildRunManifests([res("node-2", "platform/b.vma.zst", "2026/2026-10-04/node-2/vms/142-x/vzdump-qemu-142-2026_10_02-04_47_50.vma.zst.age", { vmid: 142, vmName: "x" })], "2026-10-04", ["age1abc"], new Map([["node-2", first]])).get("node-2")!;
  assert.equal(second.items.length, 2);
  assert.equal(second.run.startedAt, first.run.startedAt);
});

test("a result with an empty object is rejected (an empty backup is not a backup)", () => {
  const bad = res("n", "platform/x", "2026/2026-10-04/n/databases/x.sql.gz.age", { category: "database", vmid: undefined });
  bad.result.bytes = 0;
  assert.throws(() => buildRunManifests([bad], "2026-10-04", ["age1abc"]), /invalid/);
});

test("CLI plan-only against a real-shaped inventory: prints the plan, uploads nothing, exits 0", () => {
  const dir = mkdtempSync(path.join(tmpdir(), "up-"));
  try {
    const inv = {
      runDate: "2026-10-04",
      nodes: [{ node: "node-5", via: "agent", ok: true, vms: [{ vmid: 147, name: "valheim-1gcle3", class: "game", offsiteCadenceDays: 7, template: false }], files: [{ rel: "platform/vzdump-qemu-147-2026_10_03-02_00_00.vma.zst", size: 5e9, mtimeMs: Date.now() - 3_600_000 }] }],
      remote: [],
    };
    writeFileSync(path.join(dir, "inv.json"), JSON.stringify(inv));
    const r = spawnSync("npx", ["tsx", path.resolve(__dirname, "../scripts/backup-offsite-run.ts"), "--inventory-file", path.join(dir, "inv.json"), "--retention"], { encoding: "utf8", env: { ...process.env, DATABASE_URL: "postgresql://x:x@localhost:5432/x" }, cwd: path.resolve(__dirname, "..") });
    assert.equal(r.status, 0, r.stderr);
    assert.match(r.stdout, /PLAN ONLY: 1 upload/);
    assert.match(r.stdout, /node-5 vm 147 valheim-1gcle3/);
    assert.match(r.stdout, /2026\/2026-10-04\/node-5\/vms\/147-valheim-1gcle3\//);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});

test("CLI --execute without NXEON_OFFSITE_V2=1 refuses to upload", () => {
  const dir = mkdtempSync(path.join(tmpdir(), "up-"));
  try {
    writeFileSync(path.join(dir, "inv.json"), JSON.stringify({ runDate: "2026-10-04", nodes: [], remote: [] }));
    const r = spawnSync("npx", ["tsx", path.resolve(__dirname, "../scripts/backup-offsite-run.ts"), "--inventory-file", path.join(dir, "inv.json"), "--execute"], { encoding: "utf8", env: { ...process.env, NXEON_OFFSITE_V2: "", DATABASE_URL: "postgresql://x:x@localhost:5432/x" }, cwd: path.resolve(__dirname, "..") });
    assert.equal(r.status, 0);
    assert.match(r.stdout, /refusing to upload/);
  } finally { rmSync(dir, { recursive: true, force: true }); }
});
