/** Pure glue between the off-site remote listing / node health and the freshness evaluator + fleet alert planner. */
import { parseRemotePath, timestampFromName, nodeSlug } from "./backup-layout";
import { evaluateFreshness, headline, type Finding, type FreshnessInput, type NodeHealth, type OffsiteState } from "./backup-freshness";
import { MIN_AGE_OBJECT_BYTES, type RemoteFile } from "./backup-offsite-plan";
import type { DesiredAlert } from "./fleet-alert-plan";

/** `${node}|${category}|${vmid||0}` -> newest source timestamp, ignoring truncated objects. */
export function newestFromRemote(files: readonly RemoteFile[]): Record<string, number> {
  const out: Record<string, number> = {};
  for (const f of files) {
    const p = parseRemotePath(f.path);
    if (!p || f.size < MIN_AGE_OBJECT_BYTES) continue;
    const ts = timestampFromName(p.plainName) ?? f.mtimeMs;
    const k = `${p.node}|${p.category}|${p.vmid ?? 0}`;
    if (!(k in out) || ts > out[k]) out[k] = ts;
  }
  return out;
}

export function slugNode(n: NodeHealth): NodeHealth { return { ...n, node: nodeSlug(n.node) }; }

export type SweepResult = {
  findings: Finding[];
  desired: DesiredAlert[];
  /** nodes whose state was read, i.e. whose alerts may be auto-resolved. Fleet-level findings hang off the primary,
   *  so an unreadable remote removes the primary from this set (unverified is not recovered). */
  readNodeIds: Set<string>;
  nodeNames: Map<string, string>;
  headline: ReturnType<typeof headline>;
};

export function runSweep(input: FreshnessInput): SweepResult {
  const nodes = input.nodes.map(slugNode);
  const findings = evaluateFreshness({ ...input, nodes });
  const desired: DesiredAlert[] = findings.map((f) => ({
    nodeId: f.nodeId, nodeName: f.node, dimension: f.dimension, severity: f.severity,
    title: `Backup: ${f.title}`, detail: f.detail,
  }));
  const readNodeIds = new Set(nodes.filter((n) => n.reachable).map((n) => n.nodeId));
  const primary = nodes.find((n) => n.node === input.primaryNode);
  if (primary && !input.offsite.read) readNodeIds.delete(primary.nodeId);
  return { findings, desired, readNodeIds, nodeNames: new Map(nodes.map((n) => [n.nodeId, n.node])), headline: headline(findings) };
}

export type { OffsiteState };
