/** Reads /tank/backup/status/offsite-inventory.json (written by worker/offsite-backup-sweep.ts) for /admin/backups. Never throws. */
import { promises as fs } from "fs";
import path from "path";
import { inventoryStale, type Finding } from "./backup-freshness";

const STATUS_DIR = process.env.NXEON_BACKUP_STATUS_DIR ?? "/tank/backup/status";

export type InventoryNode = {
  node: string; reachable: boolean; error: string | null;
  timers: { name: string; enabled: boolean; active: boolean; lastTriggerMs: number | null }[];
  hypervisorNewestMs: number | null;
  backupFs: { freeBytes: number; totalBytes: number } | null;
  vms: { vmid: number; name: string; class: string; template: boolean; offsiteCadenceDays: number; localCadenceDays: number; localNewestMs: number | null }[];
};
export type OffsiteInventory = {
  generatedAt: number;
  headline: { level: "ok" | "warn" | "critical"; text: string };
  findings: Finding[];
  offsite: { read: boolean; error: string | null; usedBytes: number | null; totalBytes: number | null; timerEnabled: boolean | null; timerActive: boolean | null; lastUploadOkMs: number | null; encrypted: boolean | null; newest: Record<string, number> };
  nodes: InventoryNode[];
};
export type OffsiteInventoryView = { state: "missing" | "stale" | "ok"; inv: OffsiteInventory | null };

export async function readOffsiteInventory(now = Date.now()): Promise<OffsiteInventoryView> {
  try {
    const inv = JSON.parse(await fs.readFile(path.join(STATUS_DIR, "offsite-inventory.json"), "utf8")) as OffsiteInventory;
    return { state: inventoryStale(inv.generatedAt, now) ? "stale" : "ok", inv };
  } catch {
    return { state: "missing", inv: null };
  }
}

/** One matrix row per node x VM: newest local and newest off-site copy ages. Pure. */
export function coverageRows(inv: OffsiteInventory, now: number) {
  const rows: { node: string; vmid: number; name: string; cls: string; localAgeH: number | null; offsiteAgeH: number | null }[] = [];
  for (const n of inv.nodes) {
    for (const v of n.vms) {
      const off = inv.offsite.newest[`${n.node}|vm|${v.vmid}`];
      rows.push({ node: n.node, vmid: v.vmid, name: v.name, cls: v.class, localAgeH: v.localNewestMs == null ? null : (now - v.localNewestMs) / 3_600_000, offsiteAgeH: off == null ? null : (now - off) / 3_600_000 });
    }
  }
  return rows.sort((a, b) => a.node.localeCompare(b.node) || a.vmid - b.vmid);
}
