import { Badge, fmtBytes } from "@/components/ui/primitives";
import { coverageRows, type OffsiteInventoryView } from "@/lib/offsite-inventory-view";

const age = (h: number | null) => (h === null ? "never" : h < 48 ? `${h.toFixed(0)} h` : `${(h / 24).toFixed(1)} d`);

/**
 * Off-site coverage + freshness (read-only). Data is written hourly by worker/offsite-backup-sweep.ts
 * (NXEON_OFFSITE_FRESHNESS=1). Shows, per node and VM, the newest local and newest OFF-SITE copy, plus every
 * finding the evaluator raised. A missing or >12 h old inventory is itself shown as a warning.
 */
export function OffsiteCoveragePanel({ view }: { view: OffsiteInventoryView }) {
  if (view.state === "missing" || !view.inv) {
    return (
      <div className="card border-amber-500/30 bg-amber-500/[0.06]">
        <p className="text-sm font-semibold text-amber-300">Off-site freshness is not being checked</p>
        <p className="mt-1 text-xs text-slate-400">No inventory file yet. Set <code>NXEON_OFFSITE_FRESHNESS=1</code> for the worker (see docs/DOCUMENTATION.md, Off-site backups v2). Until then nothing alerts if off-site backups stop.</p>
      </div>
    );
  }
  const { inv } = view;
  const now = Date.now();
  const rows = coverageRows(inv, now);
  const tone = inv.headline.level === "critical" ? "red" : inv.headline.level === "warn" ? "amber" : "green";
  return (
    <div className="card space-y-4">
      <div className="flex flex-wrap items-center gap-2">
        <h2 className="font-semibold">Off-site coverage</h2>
        <Badge tone={tone as any}>{inv.headline.text}</Badge>
        {view.state === "stale" && <Badge tone="red">checker stale: last ran {age((now - inv.generatedAt) / 3_600_000)} ago</Badge>}
        <Badge tone={inv.offsite.timerEnabled && inv.offsite.timerActive ? "green" : "red"}>upload timer {inv.offsite.timerEnabled && inv.offsite.timerActive ? "running" : "NOT running"}</Badge>
        <Badge tone={inv.offsite.encrypted === true ? "green" : "red"}>{inv.offsite.encrypted === true ? "encrypted" : "encryption not confirmed"}</Badge>
        {inv.offsite.usedBytes != null && inv.offsite.totalBytes ? <Badge tone="slate">{fmtBytes(inv.offsite.usedBytes)} of {fmtBytes(inv.offsite.totalBytes)}</Badge> : null}
      </div>
      {inv.findings.length > 0 && (
        <ul className="space-y-1 text-xs">
          {inv.findings.map((f) => (
            <li key={f.dimension + f.node}><Badge tone={f.severity === "CRITICAL" ? "red" : "amber"}>{f.severity}</Badge> <span className="font-medium">{f.node}</span> — {f.title}. <span className="text-slate-400">{f.detail}</span></li>
          ))}
        </ul>
      )}
      <div className="overflow-x-auto">
        <table className="w-full text-xs">
          <thead><tr className="text-left text-slate-400"><th className="py-1 pr-3">Node</th><th className="pr-3">VM</th><th className="pr-3">Class</th><th className="pr-3">Local</th><th>Off-site</th></tr></thead>
          <tbody>
            {rows.map((r) => (
              <tr key={r.node + r.vmid} className="border-t border-white/5">
                <td className="py-1 pr-3">{r.node}</td><td className="pr-3">{r.vmid} {r.name}</td><td className="pr-3">{r.cls}</td>
                <td className="pr-3">{age(r.localAgeH)}</td><td>{age(r.offsiteAgeH)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
