const AGENT_PATH = path.resolve(__dirname, "../node-agent/index.js");

type Harness = { proc: ReturnType<typeof spawn>; base: string; dir: string };

async function startAgent(extraEnv: Record<string, string> = {}): Promise<Harness> {
  const dir = mkdtempSync(path.join(tmpdir(), "nxeon-agent-test-"));
  const keyPath = path.join(dir, "key.pem");
  const certPath = path.join(dir, "cert.pem");
  await execFile("openssl", [
    "req", "-x509", "-newkey", "rsa:2048", "-nodes",
    "-keyout", keyPath, "-out", certPath,
    "-days", "1", "-subj", "/CN=nxeon-agent-test",
  ]);

  const proc = spawn(process.execPath, [AGENT_PATH], {
    env: {
      ...process.env,
      NXEON_AGENT_PORT: String(PORT),
      NXEON_AGENT_TOKEN: TOKEN,
      NXEON_AGENT_TLS_KEY: keyPath,
      NXEON_AGENT_TLS_CERT: certPath,
      ...extraEnv,
    },
    stdio: ["ignore", "pipe", "pipe"],
  });
  let out = "";
  proc.stdout?.on("data", (d) => (out += d.toString()));
  proc.stderr?.on("data", (d) => (out += d.toString()));

  // Wait for the "listening" line rather than a fixed sleep.
  const deadline = Date.now() + 5000;
  while (!out.includes("listening") && Date.now() < deadline) {
    await new Promise((r) => setTimeout(r, 50));
    if (proc.exitCode !== null) throw new Error(`agent exited early: ${out}`);
  }
  if (!out.includes("listening")) throw new Error(`agent did not start in time: ${out}`);

  return { proc, base: `https://127.0.0.1:${PORT}`, dir };
}

function stopAgent(h: Harness) {
  h.proc.kill();
  rmSync(h.dir, { recursive: true, force: true });
}

async function call(
  base: string,
  method: string,
  path_: string,
  opts: { token?: string; body?: unknown } = {}
): Promise<{ status: number; json: any }> {
  const res = await fetch(`${base}${path_}`, {
    method,
    headers: {
      ...(opts.token !== undefined ? { Authorization: `Bearer ${opts.token}` } : {}),
      ...(opts.body !== undefined ? { "Content-Type": "application/json" } : {}),
    },
    body: opts.body !== undefined ? JSON.stringify(opts.body) : undefined,
  });
  const text = await res.text();
  let json: any = null;
  try {
    json = JSON.parse(text);
  } catch {
    /* non-JSON response */
  }
  return { status: res.status, json };
}

