/**
 * The lowest vmid a brand-new server may start probing from: above every id
 * the platform has ever handed out, never `/cluster/nextid`'s "lowest free"
 * on its own.
 *
 * WHY (2026-10-01): `nextid` returns the lowest FREE id, i.e. the one a
 * deleted server just gave back. The owner's standing rule is that a VMID is
 * never reused fleet-wide (a recycled id silently collides with stale DB rows,
 * backups, NAT rules and monitoring series — see the 2026-09-06 incidents in
 * docs). The archive check in pickProvisionVmid only covers the backup case.
 * Observed on node-5 the same day this was written: vmids 117 and 142-145
 * destroyed in the early hours and 117/142/143 handed straight back out to new
 * servers hours later.
 *
 * `usedVmids` = every vmid currently on a Server row (sandbox + template-range
 * ids ignored); the caller also folds in a persisted high-water mark so ids of
 * DELETED servers (whose rows are gone) still count. The result skips the
 * template range entirely.
 */
export function freshVmidFloor(nextVmid: number, usedVmids: Iterable<number>): number {
  let high = 0;
  for (const v of usedVmids) {
    if (!Number.isInteger(v) || v <= 0) continue;
    if (v >= SANDBOX_VMID_MIN) continue;
    if (v >= TEMPLATE_VMID_MIN && v <= TEMPLATE_VMID_MAX) continue;
    if (v > high) high = v;
  }
  let c = Math.max(Number.isInteger(nextVmid) && nextVmid > 0 ? nextVmid : 100, high + 1);
  while (RESERVED_VMIDS.has(c)) c++;
  if (c >= TEMPLATE_VMID_MIN && c <= TEMPLATE_VMID_MAX) c = TEMPLATE_VMID_MAX + 1;
  return c;
}

export function pickProvisionVmid(opts: {
  candidate: number;
  takenVmids: ReadonlySet<number>;
  archivedVmids: ReadonlySet<number>;
  maxProbe?: number;
}): { vmid: number; skipped: number[]; skippedTaken: number[]; skippedArchived: number[] } {
  const { candidate, takenVmids, archivedVmids } = opts;
  const maxProbe = opts.maxProbe ?? 512;
  if (!Number.isInteger(candidate) || candidate <= 0) {
    throw new Error(`pickProvisionVmid: '${candidate}' is not a usable vmid`);
  }
  const skipped: number[] = [];
  // WHY each id was skipped, not just that it was. The two reasons call for
  // completely different operator actions — "reap the orphaned archives" is
  // useless advice when the id is simply another live server's — and the caller
  // used to report every skip as an archive. Observed 2026-09-06 on node-2:
  // eight ids skipped, logged as archive-holders, when seven were live customer
  // VMs on the PRIMARY (Server.vmid is unique app-wide) and exactly one (108)
  // actually held an archive.

