function sandbox() {
  const dir = mkdtempSync(path.join(tmpdir(), "wr-"));
  const bin = path.join(dir, "bin"); mkdirSync(bin);
  const stub = (n: string, body: string) => { writeFileSync(path.join(bin, n), `#!/bin/bash\n${body}\n`); chmodSync(path.join(bin, n), 0o755); };
  return { dir, bin, stub, clean: () => rmSync(dir, { recursive: true, force: true }) };
}

function watch(o: { offsiteTimer?: string; runTimer?: string; legacy?: string; offsiteJson?: object | null }) {
  const s = sandbox();
  try {
    const st = path.join(s.dir, "status"); mkdirSync(st);
    const root = path.join(s.dir, "root"); mkdirSync(root);
    const tm: Record<string, string> = { "nxeon-backup-offsite.timer": o.offsiteTimer ?? "enabled/active", "nxeon-backup-run.timer": o.runTimer ?? "disabled/inactive", "nxeon-backup-vms.timer": o.legacy ?? "enabled/active" };
    s.stub("systemctl", `case "$1" in is-enabled) case "$2" in ${Object.entries(tm).map(([k, v]) => `${k}) echo ${v.split("/")[0]};;`).join(" ")} esac;; is-active) case "$2" in ${Object.entries(tm).map(([k, v]) => `${k}) echo ${v.split("/")[1]};;`).join(" ")} esac;; esac`);
    if (o.offsiteJson !== null) writeFileSync(path.join(st, "offsite.json"), JSON.stringify(o.offsiteJson ?? { ok: true, lastSuccessAt: new Date((NOW - 6 * 3600) * 1000).toISOString(), encrypted: true }));
    const r = spawnSync("bash", [WATCH], { encoding: "utf8", env: { PATH: `${s.bin}:${process.env.PATH}`, NXEON_BACKUP_STATUS_DIR: st, NXEON_BACKUP_ROOT: root, NXEON_WATCH_NOW: String(NOW) } });
    return { code: r.status, out: r.stdout };
  } finally { s.clean(); }
}

