/** Pure: Server rows -> per-node /etc/nxeon/backup-policy.json overrides for nxeon-backup-plan.py. */
import { isGameFamily } from "./games";

export type PolicyServer = {
  vmid: number | null;
  nodeName: string;
  osFamily: string;
  backupTier: string | null;
  autoBackup: boolean;
  addons: unknown;
};
export type NodePolicy = { vms: Record<string, { class?: string; offsiteCadenceDays?: number }> };

/** Paid-backup customers get a fresher off-site copy (2 days instead of 7). Their OWN backups are never touched or pruned by the platform DR job. */
export const PAID_BACKUP_OFFSITE_DAYS = 2;

export function exportPolicies(servers: readonly PolicyServer[]): Map<string, NodePolicy> {
  const out = new Map<string, NodePolicy>();
  for (const s of servers) {
    if (!s.vmid) continue;
    const p = out.get(s.nodeName) ?? out.set(s.nodeName, { vms: {} }).get(s.nodeName)!;
    const cls = isGameFamily(s.osFamily) ? "game" : "customer-vps";
    const entry: { class?: string; offsiteCadenceDays?: number } = { class: cls };
    const addons = (s.addons ?? {}) as { dailyBackup?: boolean };
    if ((s.backupTier && s.backupTier !== "FREE") || addons.dailyBackup === true) entry.offsiteCadenceDays = PAID_BACKUP_OFFSITE_DAYS;
    p.vms[String(s.vmid)] = entry;
  }
  return out;
}
EOF
cat > scripts/backup-policy-export.ts <<'EOF'
/**
 * READ-ONLY: print, per node, the /etc/nxeon/backup-policy.json overrides derived from the database
 * (game family of each server's image; paid-backup customers get a fresher off-site copy).
 *   npx tsx scripts/backup-policy-export.ts [--out-dir DIR]
 * Writes nothing to the DB or any node. Ship a node's file to /etc/nxeon/backup-policy.json yourself (scp) after review.
 */
import { promises as fs } from "node:fs";
import path from "node:path";
import { db } from "../lib/db";
import { exportPolicies } from "../lib/backup-policy-export";

async function main() {
  const rows = await db.server.findMany({
    where: { vmid: { not: null }, nodeId: { not: null }, status: { notIn: ["DELETING"] } },
    select: { vmid: true, backupTier: true, autoBackup: true, addons: true, osTemplate: { select: { family: true } }, node: { select: { name: true } } },
  } as any);
  const servers = (rows as any[]).map((r) => ({ vmid: r.vmid, nodeName: r.node?.name ?? "unknown", osFamily: r.osTemplate?.family ?? "", backupTier: r.backupTier, autoBackup: r.autoBackup, addons: r.addons }));
  const outDir = process.argv.includes("--out-dir") ? process.argv[process.argv.indexOf("--out-dir") + 1] : null;
  for (const [node, policy] of exportPolicies(servers)) {
    const json = JSON.stringify({ _comment: `generated ${new Date().toISOString()} from the database for ${node}`, vms: policy.vms }, null, 2);
    if (outDir) { await fs.mkdir(outDir, { recursive: true }); await fs.writeFile(path.join(outDir, `${node}.backup-policy.json`), json + "\n"); }
    else console.log(`# ${node}\n${json}`);
  }
}
main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
EOF
cat > scripts/backup-window-report.ts <<'EOF'
/**
 * READ-ONLY: compute each node's quietest backup window from the last 28 days of game player sessions
 * (+ portal visits as a weak tie-break) and print the recommendation with its evidence.
 *   npx tsx scripts/backup-window-report.ts [--hours 4] [--out-dir DIR]
 * Reads PlayerSession / Visit / Server / Node only. Writes only the optional JSON files under --out-dir
 * ({"startUtc":"18:00","hours":4}); ship one to /etc/nxeon/backup-window.json on that node after review.
 */
import { promises as fs } from "node:fs";
import path from "node:path";
import { db } from "../lib/db";
import { playerProfile, visitProfile, selectBackupWindow } from "../lib/backup-window";

const DAYS = 28;
async function main() {
  const hours = process.argv.includes("--hours") ? Number(process.argv[process.argv.indexOf("--hours") + 1]) : 4;
  const outDir = process.argv.includes("--out-dir") ? process.argv[process.argv.indexOf("--out-dir") + 1] : null;
  const now = Date.now();
  const since = new Date(now - DAYS * 86_400_000);
  const nodes = await db.node.findMany({ select: { id: true, name: true, region: true } });
  const visits = await db.visit.findMany({ where: { createdAt: { gte: since }, kind: "portal" }, select: { createdAt: true } });
  const vp = visitProfile(visits.map((v) => v.createdAt.getTime()), now, DAYS);
  for (const n of nodes) {
    const sessions = await db.playerSession.findMany({
      where: { server: { nodeId: n.id }, OR: [{ leftAt: null }, { leftAt: { gte: since } }] },
      select: { joinedAt: true, leftAt: true },
    });
    const pp = playerProfile(sessions.map((s) => ({ start: s.joinedAt.getTime(), end: s.leftAt ? s.leftAt.getTime() : null })), now, DAYS);
    const w = selectBackupWindow({ playerAvg: pp.playerAvg, playerHours: pp.playerHours, visitAvg: vp.visitAvg, visits: vp.visits, days: DAYS, region: n.region, durationHours: hours, now });
    console.log(`${n.name} (${n.region}): ${w.startUtc} UTC + ${w.hours} h  [${w.basis}]\n  ${w.explanation}`);
    if (outDir) { await fs.mkdir(outDir, { recursive: true }); await fs.writeFile(path.join(outDir, `${n.name}.backup-window.json`), JSON.stringify({ startUtc: w.startUtc, hours: w.hours }) + "\n"); }
  }
}
main().then(() => process.exit(0)).catch((e) => { console.error(e); process.exit(1); });
EOF
